chmod 644 /usr/share/fasdeqos/system.list
cat >/etc/pacman.d/hooks/fasd-layout.hook <<'EOF_FASD_LAYOUT_HOOK'
[Trigger]
Operation = Install
Operation = Remove
Operation = Upgrade
Type = Package
Target = *

[Action]
