EOF_FASD_LAYOUT_HOOK
chmod 644 /etc/pacman.d/hooks/fasd-layout.hook
cat >/usr/local/bin/fasd-first <<'EOF_FASD_FIRST'
#!/bin/sh
icons() {
    for d in /Applications/*.app; do
        [ -d "$d" ] || continue
        gio info -a metadata::custom-icon "$d" 2>/dev/null | grep -q 'custom-icon' && continue
        ic=$(sed -n 's/^Icon=//p' "$d/Contents/Desktop" 2>/dev/null | head -n 1)
        [ -n "$ic" ] || continue
        case "$ic" in
            /*) f=$ic ;;
            *) f=$(find /usr/share/icons/Papirus-Dark/64x64/apps /usr/share/icons/hicolor/scalable/apps /usr/share/icons/hicolor/256x256/apps /usr/share/pixmaps /usr/local/share/icons /usr/local/share/fasdeqos/icons -name "$ic.*" 2>/dev/null | head -n 1) ;;
        esac
        [ -n "$f" ] && gio set "$d" metadata::custom-icon "file://$f" 2>/dev/null
    done
}
M=$HOME/.config/fasdeqos/first-done
if [ ! -f "$M" ]; then
    mkdir -p "$HOME/.config/fasdeqos" "$HOME/.config/gtk-3.0"
    xdg-user-dirs-update
    {
        echo "file:///Applications Applications"
        for k in DOWNLOAD DOCUMENTS PICTURES MUSIC VIDEOS; do
            d=$(xdg-user-dir "$k")
            echo "file://$d $(basename "$d")"
        done
    } >"$HOME/.config/gtk-3.0/bookmarks"
    starship preset catppuccin-powerline -o "$HOME/.config/starship.toml" 2>/dev/null
    gsettings set org.gnome.desktop.interface icon-theme Papirus-Dark
    gsettings set org.gnome.desktop.interface color-scheme prefer-dark
    gsettings set org.gnome.desktop.interface gtk-theme Adwaita-dark
    gsettings set com.github.stunkymonkey.nautilus-open-any-terminal terminal ghostty 2>/dev/null
    /usr/local/bin/fasd-outputs
    touch "$M"
fi
[ -f "$HOME/.config/niri/colors.kdl" ] || : >"$HOME/.config/niri/colors.kdl"
icons
exit 0
EOF_FASD_FIRST
chmod 755 /usr/local/bin/fasd-first
cat >/usr/local/bin/fasd-outputs <<'EOF_FASD_OUTPUTS'
#!/bin/sh
C=$HOME/.config/niri/config.kdl
n=0
while [ $n -lt 100 ]; do
    niri msg version >/dev/null 2>&1 && break
    n=$((n + 1))
    sleep 0.2
done
json=$(niri msg --json outputs 2>/dev/null) || exit 0
printf '%s' "$json" | awk 'BEGIN { RS = "\"name\":\"" }
NR > 1 {
    name = substr($0, 1, index($0, "\"") - 1)
    bw = 0; bh = 0; br = 0
    s = $0
    while (match(s, /"width":[0-9]+,"height":[0-9]+,"refresh_rate":[0-9]+/)) {
        m = substr(s, RSTART, RLENGTH)
        s = substr(s, RSTART + RLENGTH)
        split(m, a, /[^0-9]+/)
        w = a[2] + 0; h = a[3] + 0; r = a[4] + 0
        if (w * h > bw * bh || (w * h == bw * bh && r > br)) { bw = w; bh = h; br = r }
    }
    v = (index($0, "\"vrr_supported\":true") > 0) ? 1 : 0
    if (bw > 0) printf "%s %dx%d@%d.%03d %d\n", name, bw, bh, int(br / 1000), br % 1000, v
}' | while read -r name mode vrr; do
    niri msg output "$name" mode "$mode" >/dev/null 2>&1
    [ -f "$C" ] || continue
    grep -q "^output \"$name\"" "$C" && continue
    {
        printf '\noutput "%s" {\n    mode "%s"\n' "$name" "$mode"
        [ "$vrr" = 1 ] && printf '    variable-refresh-rate on-demand=true\n'
        printf '}\n'
    } >>"$C"
done
exit 0
EOF_FASD_OUTPUTS
chmod 755 /usr/local/bin/fasd-outputs
cat >/usr/local/bin/fasd-fasdquery <<'EOF_FASD_FASDQUERY'
#!/bin/sh
PB=/System/pkg-backend; [ -x "$PB" ] || PB=pacman
[ "$(id -u)" = 0 ] || exec doas "$0" "$@"
T=$(mktemp -d)
"$PB" -S --needed --asdeps --noconfirm cmake ninja gcc qt6-svg git >/dev/null 2>&1
if git clone --depth 1 https://github.com/Fasdeq13/FasdQuery.git "$T/src" >/dev/null 2>&1 \
    && cmake -S "$T/src" -B "$T/b" -G Ninja -DCMAKE_BUILD_TYPE=Release >/dev/null 2>&1 \
    && ninja -C "$T/b" >/dev/null 2>&1; then
    install -Dm755 "$T/b/FasdQuery" /usr/local/bin/FasdQuery
    install -Dm644 "$T/src/app_icon.svg" /usr/share/icons/hicolor/scalable/apps/fasdquery.svg
    mkdir -p /usr/local/share/applications
    printf '[Desktop Entry]\nType=Application\nName=FasdQuery\nComment=File search\nExec=/usr/local/bin/FasdQuery\nIcon=fasdquery\nCategories=Utility;\nTerminal=false\n' >/usr/local/share/applications/fasdquery.desktop
    gtk-update-icon-cache -f /usr/share/icons/hicolor >/dev/null 2>&1
    /usr/local/bin/fasd-layout
    rm -rf "$T"
    exit 0
fi
rm -rf "$T"
echo "FasdQuery was not built"
exit 1
EOF_FASD_FASDQUERY
chmod 755 /usr/local/bin/fasd-fasdquery
cat >/usr/local/bin/fastab <<'EOF_FASTAB'
#!/bin/sh
case "${LC_ALL:-${LANG:-en}}" in
    ru*) T1="fastab: выбор дисков для автомонтирования"; T2="Стрелки: выбор   Пробел: отметить   o: параметры   Enter: применить   q: выход"; T3="Нет дисков, которых нет в fstab"; T4="Параметры монтирования (пусто = defaults): "; T5="Готово. Диски смонтируются при следующей загрузке."; T6="Нужен root"; T7="Применено";;
    uk*) T1="fastab: вибір дисків для автомонтування"; T2="Стрілки: вибір   Пробіл: позначити   o: параметри   Enter: застосувати   q: вихід"; T3="Немає дисків, яких нема у fstab"; T4="Параметри монтування (порожньо = defaults): "; T5="Готово. Диски змонтуються при наступному завантаженні."; T6="Потрібен root"; T7="Застосовано";;
    *) T1="fastab: pick disks to mount at boot"; T2="Arrows: move   Space: toggle   o: options   Enter: apply   q: quit"; T3="No disks missing from fstab"; T4="Mount options (empty = defaults): "; T5="Done. Disks will be mounted on next boot."; T6="Root required"; T7="Applied";;
esac
[ "$(id -u)" = 0 ] || exec doas /usr/local/bin/fastab "$@"
FSTAB=/etc/fstab
LIST=$(mktemp)
blkid | while IFS= read -r l; do
    dev=${l%%:*}
    uuid=$(echo "$l" | sed -n 's/.* UUID="\([^"]*\)".*/\1/p')
    typ=$(echo "$l" | sed -n 's/.* TYPE="\([^"]*\)".*/\1/p')
    lab=$(echo "$l" | sed -n 's/.* LABEL="\([^"]*\)".*/\1/p')
    case "$typ" in ext4|ext3|ext2|btrfs|vfat|xfs|f2fs|exfat|ntfs) ;; *) continue;; esac
    [ -n "$uuid" ] || continue
    grep -q "$uuid" "$FSTAB" 2>/dev/null && continue
    cm=$(findmnt -rno TARGET "$dev" 2>/dev/null | head -n 1)
    case "$cm" in /|/boot|/boot/*|/efi|/Users) continue ;; esac
    sz=$(awk -v d="${dev#/dev/}" '$4 == d {printf "%.1fG", $3/1048576}' /proc/partitions)
    echo "$dev|$uuid|$typ|${lab:-${dev#/dev/}}|$sz|defaults|0" >>"$LIST"
done
N=$(wc -l <"$LIST")
[ "$N" -gt 0 ] || { echo "$T3"; rm -f "$LIST"; exit 0; }
OLD=$(stty -g)
trap 'stty "$OLD"; rm -f "$LIST"; printf "\033[?25h"' EXIT INT TERM
stty -icanon -echo min 1 time 0
cur=1
draw() {
    printf '\033[H\033[2J\033[1m%s\033[0m\n%s\n\n' "$T1" "$T2"
    i=1
    while IFS='|' read -r dev uuid typ lab sz opt sel; do
        m=" "; [ "$sel" = 1 ] && m="x"
        p="  "; [ "$i" = "$cur" ] && p="> "
        [ "$i" = "$cur" ] && printf '\033[7m'
        printf '%s[%s] %-12s %-6s %-8s %-16s %s\033[0m\n' "$p" "$m" "$dev" "$typ" "$sz" "$lab" "$opt"
        i=$((i+1))
    done <"$LIST"
}
setfield() {
    awk -F'|' -v OFS='|' -v n="$1" -v f="$2" -v v="$3" 'NR == n {$f = v} {print}' "$LIST" >"$LIST.n" && cat "$LIST.n" >"$LIST"; rm -f "$LIST.n"
}
getfield() { sed -n "${1}p" "$LIST" | cut -d'|' -f"$2"; }
printf '\033[?25l'
while :; do
    draw
    k=$(dd bs=1 count=1 2>/dev/null)
    case "$k" in
        q) exit 0;;
        " ") s=$(getfield "$cur" 7); [ "$s" = 1 ] && s=0 || s=1; setfield "$cur" 7 "$s";;
        o) printf '\033[?25h\n%s' "$T4"; stty "$OLD"; read -r o; stty -icanon -echo min 1 time 0; printf '\033[?25l'; [ -n "$o" ] || o=defaults; setfield "$cur" 6 "$o";;
        j) [ "$cur" -lt "$N" ] && cur=$((cur+1));;
        k) [ "$cur" -gt 1 ] && cur=$((cur-1));;
        "$(printf '\n')"|"")
            while IFS='|' read -r dev uuid typ lab sz opt sel; do
                [ "$sel" = 1 ] || continue
                mp="/Mount/$(echo "$lab" | tr ' /' '__')"
                mkdir -p "$mp"
                umount "$dev" 2>/dev/null
                [ "$typ" = ntfs ] && typ=ntfs3
                pass=2; [ "$typ" = vfat ] || [ "$typ" = exfat ] && pass=0
                echo "UUID=$uuid $mp $typ $opt 0 $pass" >>"$FSTAB"
                mount "$mp" 2>/dev/null
                case "$typ" in ext4|ext3|ext2|btrfs|xfs|f2fs) [ "$(stat -c %u "$mp")" = 0 ] && chown 1000:1000 "$mp" ;; esac
            done <"$LIST"
            printf '\033[H\033[2J%s\n' "$T5"
            exit 0;;
        "$(printf '\033')")
            r=$(dd bs=1 count=2 2>/dev/null)
            case "$r" in
                "[A") [ "$cur" -gt 1 ] && cur=$((cur-1));;
                "[B") [ "$cur" -lt "$N" ] && cur=$((cur+1));;
            esac;;
    esac
done
EOF_FASTAB
chmod 755 /usr/local/bin/fastab
mkdir -p /usr/share/fasdeqos/quickshell /usr/share/fasdeqos/theme /usr/share/backgrounds/fasdeqos /Applications/shells
cat >/usr/share/fasdeqos/quickshell/shell.qml <<'EOF_QS_SHELL_QML'
//@ pragma UseQApplication
import QtQuick
import QtQuick.Controls
import QtQuick.Layouts
import Quickshell
import Quickshell.Io
import Quickshell.Wayland
import Quickshell.Services.SystemTray
import Quickshell.Services.Pipewire

ShellRoot {
    id: root

    property bool wifiMenu: false
    property bool bluetoothMenu: false
    property bool audioMenu: false
    property bool calendarMenu: false
    property bool screenshotMenu: false

    property bool wifiAvailable: false
    property bool wifiEnabled: false
    property bool wifiBusy: false
    property string ethernetDevice: ""
    property bool ethernetConnected: false
    property bool bluetoothEnabled: false

    property var niriWorkspaces: []
    property var keyboardLayouts: []
    property int currentLayoutIdx: 0
    property string currentLayoutShort: {
        if (!keyboardLayouts || keyboardLayouts.length === 0)
            return "EN"
        let name = String(keyboardLayouts[currentLayoutIdx] || "").toLowerCase()
        if (name.includes("russian") || name.includes("ru"))
            return "RU"
        if (name.includes("english") || name.includes("us"))
            return "EN"
        return name.substring(0, 2).toUpperCase()
    }

    property string currentDate: Qt.formatDateTime(new Date(), "dd.MM  HH:mm")
    property int calYear: new Date().getFullYear()
    property int calMonth: new Date().getMonth()

    property var wifiNetworks: []
    property var bluetoothDevices: []

    property var audioSink: Pipewire.defaultAudioSink
    property var audioSource: Pipewire.defaultAudioSource

    property real outputVolume: audioSink && audioSink.audio ? audioSink.audio.volume * 100 : 0
    property real inputVolume: audioSource && audioSource.audio ? audioSource.audio.volume * 100 : 0
    property bool outputMuted: audioSink && audioSink.audio ? audioSink.audio.muted : false
    property bool inputMuted: audioSource && audioSource.audio ? audioSource.audio.muted : false

    property bool osdVisible: false
    property bool osdReady: false

    onOutputVolumeChanged: {
        if (osdReady) showVolumeOsd()
    }

    onOutputMutedChanged: {
        if (osdReady) showVolumeOsd()
    }

    IpcHandler {
        target: "shell"
        function launcher(): void { root.closeMenus(); settingsWindow.close(); popups.toggleLauncher() }
        function power(): void { root.closeMenus(); settingsWindow.close(); popups.togglePower() }
        function settings(): void { root.closeMenus(); popups.closeLauncher(); popups.closePower(); settingsWindow.toggle() }
        function screenshot(): void { root.toggleMenu("screenshot") }
        function screenshotArea(): void { root.closeMenus(); root.niriAction(["screenshot"]) }
        function screenshotScreen(): void { root.closeMenus(); root.niriAction(["screenshot-screen"]) }
        function screenshotWindow(): void { root.closeMenus(); root.niriAction(["screenshot-window"]) }
        function calendar(): void { root.toggleMenu("calendar") }
        function audio(): void { root.toggleMenu("audio") }
        function wifi(): void { root.toggleMenu("wifi") }
        function network(): void { root.toggleMenu("wifi") }
        function bluetooth(): void { root.toggleMenu("bluetooth") }
    }

    PwObjectTracker {
        objects: [
            Pipewire.defaultAudioSink,
            Pipewire.defaultAudioSource
        ]
    }

    Timer {
        interval: 1200
        running: true
        repeat: false
        onTriggered: root.osdReady = true
    }

    Timer {
        id: osdHideTimer
        interval: 1500
        repeat: false
        onTriggered: root.osdVisible = false
    }

    function showVolumeOsd() {
        osdVisible = true
        osdHideTimer.restart()
    }

    function run(command) {
        Quickshell.execDetached(command)
    }

    function niriAction(args) {
        Quickshell.execDetached(["niri", "msg", "action"].concat(args))
    }

    function closeMenus() {
        wifiMenu = false
        bluetoothMenu = false
        audioMenu = false
        calendarMenu = false
        screenshotMenu = false
    }

    function toggleMenu(name) {
        let wasOpen = (name === "wifi" && wifiMenu) ||
                      (name === "bluetooth" && bluetoothMenu) ||
                      (name === "audio" && audioMenu) ||
                      (name === "calendar" && calendarMenu) ||
                      (name === "screenshot" && screenshotMenu)
        closeMenus()
        popups.closeLauncher()
        popups.closePower()
        settingsWindow.close()
        if (!wasOpen) {
            if (name === "wifi") {
                wifiMenu = true
                refreshWifi()
            } else if (name === "bluetooth") {
                bluetoothMenu = true
                refreshBluetooth()
            } else if (name === "audio") {
                audioMenu = true
            } else if (name === "screenshot") {
                screenshotMenu = true
            } else if (name === "calendar") {
                let now = new Date()
                calYear = now.getFullYear()
                calMonth = now.getMonth()
                calendarMenu = true
            }
        }
    }

    function refreshWifi() {
        wifiRadio.running = true
        wifiHardware.running = true
        ethDeviceProc.running = true
        wifiList.running = true
    }

    function refreshBluetooth() {
        bluetoothInfo.running = true
        bluetoothList.running = true
    }

    function toggleWifi() {
        wifiBusy = true
        wifiActionProc.command = ["nmcli", "radio", "wifi", wifiEnabled ? "off" : "on"]
        wifiActionProc.running = true
    }

    function toggleEthernet() {
        if (!ethernetDevice) return
        wifiBusy = true
        wifiActionProc.command = ["nmcli", "device", ethernetConnected ? "disconnect" : "connect", ethernetDevice]
        wifiActionProc.running = true
    }

    function scanWifi() {
        wifiBusy = true
        wifiActionProc.command = ["nmcli", "device", "wifi", "rescan"]
        wifiActionProc.running = true
    }

    function connectWifi(ssid) {
        wifiBusy = true
        wifiActionProc.command = ["nmcli", "device", "wifi", "connect", ssid]
        wifiActionProc.running = true
    }

    function toggleBluetooth() {
        run(["bluetoothctl", "power", bluetoothEnabled ? "off" : "on"])
        bluetoothRefresh.start()
    }

    function connectBluetooth(address) {
        run(["bluetoothctl", "connect", address])
    }

    function parseWifi(data) {
        let lines = data.trim().split("\n")
        let result = []
        let seen = {}
        for (let line of lines) {
            let parts = line.split(":")
            if (parts.length < 4 || !parts[1] || seen[parts[1]])
                continue
            seen[parts[1]] = true
            result.push({
                connected: parts[0] === "*",
                ssid: parts[1],
                signal: parts[2],
                security: parts.slice(3).join(":")
            })
        }
        wifiNetworks = result
    }

    function parseBluetooth(data) {
        let lines = data.trim().split("\n")
        let result = []
        for (let line of lines) {
            let match = line.match(/^Device\s+([0-9A-Fa-f:]+)\s+(.+)$/)
            if (match) {
                result.push({
                    address: match[1],
                    name: match[2]
                })
            }
        }
        bluetoothDevices = result
    }

    function calendarDays(year, month) {
        let firstDay = new Date(year, month, 1).getDay()
        let startOffset = (firstDay + 6) % 7
        let daysInMonth = new Date(year, month + 1, 0).getDate()
        let today = new Date()
        let cells = []
        for (let i = 0; i < startOffset; i++)
            cells.push({ day: "", isToday: false })
        for (let d = 1; d <= daysInMonth; d++) {
            cells.push({
                day: String(d),
                isToday: year === today.getFullYear() && month === today.getMonth() && d === today.getDate()
            })
        }
        return cells
    }

    function shiftMonth(delta) {
        let m = calMonth + delta
        if (m < 0) {
            calMonth = 11
            calYear -= 1
        } else if (m > 11) {
            calMonth = 0
            calYear += 1
        } else {
            calMonth = m
        }
    }

    Process {
        id: wifiActionProc
        onExited: wifiRefresh.restart()
    }

    Process {
        id: niriWsFetch
        command: ["niri", "msg", "-j", "workspaces"]
        running: true
        stdout: StdioCollector {
            onStreamFinished: {
                try {
                    root.niriWorkspaces = JSON.parse(text)
                } catch (e) {}
            }
        }
    }

    Process {
        id: niriKbFetch
        command: ["niri", "msg", "-j", "keyboard-layouts"]
        running: true
        stdout: StdioCollector {
            onStreamFinished: {
                try {
                    let obj = JSON.parse(text)
                    root.keyboardLayouts = obj.names || []
                    root.currentLayoutIdx = obj.current_idx || 0
                } catch (e) {}
            }
        }
    }

    Process {
        id: niriEventProc
        command: ["niri", "msg", "-j", "event-stream"]
        running: true
        stdout: SplitParser {
            onRead: data => {
                try {
                    let ev = JSON.parse(data)
                    if (ev.WorkspacesChanged) {
                        root.niriWorkspaces = ev.WorkspacesChanged.workspaces
                    } else if (ev.WorkspaceActivated) {
                        niriWsFetch.running = true
                    } else if (ev.KeyboardLayoutsChanged) {
                        let kb = ev.KeyboardLayoutsChanged.keyboard_layouts
                        root.keyboardLayouts = kb.names || []
                        root.currentLayoutIdx = kb.current_idx || 0
                    } else if (ev.KeyboardLayoutSwitched) {
                        root.currentLayoutIdx = ev.KeyboardLayoutSwitched.idx
                    }
                } catch (e) {}
            }
        }
    }

    Timer {
        interval: 1000
        repeat: true
        running: true
        onTriggered: root.currentDate = Qt.formatDateTime(new Date(), "dd.MM  HH:mm")
    }

    Timer {
        id: wifiRefresh
        interval: 800
        repeat: false
        onTriggered: {
            root.refreshWifi()
            root.wifiBusy = false
        }
    }

    Timer {
        id: bluetoothRefresh
        interval: 1000
        repeat: false
        onTriggered: root.refreshBluetooth()
    }

    Process {
        id: wifiRadio
        command: ["nmcli", "-t", "-f", "WIFI", "radio"]
        stdout: StdioCollector {
            onStreamFinished: root.wifiEnabled = text.trim() === "enabled"
        }
    }

    Process {
        id: wifiHardware
        command: ["bash", "-c", "nmcli -t -f DEVICE,TYPE device status | grep ':wifi$'"]
        stdout: StdioCollector {
            onStreamFinished: root.wifiAvailable = text.trim().length > 0
        }
    }

    Process {
        id: ethDeviceProc
        command: ["nmcli", "-t", "-f", "DEVICE,TYPE,STATE", "device", "status"]
        stdout: StdioCollector {
            onStreamFinished: {
                let lines = text.trim().split("\n")
                let dev = ""
                let conn = false
                for (let i = 0; i < lines.length; i++) {
                    let parts = lines[i].split(":")
                    if (parts.length >= 3 && parts[1] === "ethernet") {
                        dev = parts[0]
                        conn = parts[2] === "connected"
                        break
                    }
                }
                root.ethernetDevice = dev
                root.ethernetConnected = conn
            }
        }
    }

    Process {
        id: wifiList
        command: ["nmcli", "-t", "-f", "IN-USE,SSID,SIGNAL,SECURITY", "device", "wifi", "list"]
        stdout: StdioCollector {
            onStreamFinished: root.parseWifi(text)
        }
    }

    Process {
        id: bluetoothInfo
        command: ["bluetoothctl", "show"]
        stdout: StdioCollector {
            onStreamFinished: root.bluetoothEnabled = text.includes("Powered: yes")
        }
    }

    Process {
        id: bluetoothList
        command: ["bluetoothctl", "devices", "Paired"]
        stdout: StdioCollector {
            onStreamFinished: root.parseBluetooth(text)
        }
    }

    Component.onCompleted: {
        refreshWifi()
        refreshBluetooth()
    }

    Popups {
        id: popups
    }

    Settings {
        id: settingsWindow
    }

    PanelWindow {
        id: menuBackdrop
        visible: root.wifiMenu || root.bluetoothMenu || root.audioMenu || root.calendarMenu || root.screenshotMenu
        anchors {
            top: true
            bottom: true
            left: true
            right: true
        }
        color: "transparent"
        exclusionMode: ExclusionMode.Ignore
        WlrLayershell.layer: WlrLayer.Top
        WlrLayershell.namespace: "fasdeqos-backdrop"

        MouseArea {
            anchors.fill: parent
            onClicked: root.closeMenus()
        }
    }

    PanelWindow {
        id: osdWindow
        property real osdAnim: root.osdVisible ? 1 : 0
        Behavior on osdAnim {
            NumberAnimation { duration: 240; easing.type: Easing.OutExpo }
        }

        visible: root.osdVisible || osdAnim > 0.01
        anchors {
            right: true
        }
        margins {
            right: 14
        }
        implicitWidth: 56
        implicitHeight: 204
        color: "transparent"
        exclusionMode: ExclusionMode.Ignore
        WlrLayershell.layer: WlrLayer.Overlay
        WlrLayershell.namespace: "fasdeqos-osd"

        Rectangle {
            anchors.fill: parent
            radius: Colors.uiRadius
            color: Colors.cSurface
            border.width: 1
            border.color: Colors.cOutlineVariant
            opacity: osdWindow.osdAnim
            scale: 0.92 + 0.08 * osdWindow.osdAnim
            transform: Translate { x: (1 - osdWindow.osdAnim) * 16 }

            ColumnLayout {
                anchors.fill: parent
                anchors.margins: 10
                spacing: 10

                Text {
                    Layout.alignment: Qt.AlignHCenter
                    text: root.outputMuted ? "󰖁" : "󰕾"
                    color: root.outputMuted ? Colors.cInactive : Colors.cPrimary
                    font.family: Colors.cFontFamily
                    font.pixelSize: 18
                }

                Item {
                    Layout.fillHeight: true
                    Layout.alignment: Qt.AlignHCenter
                    width: 8

                    Rectangle {
                        anchors.fill: parent
                        radius: 4
                        color: Colors.cSurfaceContainerHighest

                        Rectangle {
                            anchors.bottom: parent.bottom
                            anchors.left: parent.left
                            anchors.right: parent.right
                            radius: 4
                            height: parent.height * Math.max(0, Math.min(1, root.outputVolume / 100))
                            color: root.outputMuted ? Colors.cInactive : Colors.cPrimary

                            Behavior on height {
                                NumberAnimation { duration: 140; easing.type: Easing.OutCubic }
                            }
                        }
                    }
                }

                Text {
                    Layout.alignment: Qt.AlignHCenter
                    text: Math.round(root.outputVolume) + "%"
                    color: Colors.cOnSurface
                    font.family: Colors.cFontFamily
                    font.pixelSize: 10
                    font.weight: Font.Bold
                }
            }
        }
    }

    component M3Switch: Rectangle {
        id: sw
        property bool checked: false
        property bool enabled: true
        signal toggled(bool value)

        width: 42
        height: 22
        radius: Colors.smallRadius
        opacity: enabled ? 1 : 0.45
        color: checked ? Colors.cPrimary : Colors.cSurfaceContainerHighest
        border.width: 1
        border.color: checked ? Colors.cPrimary : Colors.cOutline

        Behavior on color { ColorAnimation { duration: 200 } }

        Rectangle {
            width: 16
            height: 16
            radius: Math.max(2, Colors.smallRadius - 2)
            anchors.verticalCenter: parent.verticalCenter
            x: sw.checked ? parent.width - width - 3 : 3
            color: sw.checked ? Colors.cOnPrimary : Colors.cOnSurfaceVariant

            Behavior on x { NumberAnimation { duration: 220; easing.type: Easing.OutExpo } }
        }

        MouseArea {
            anchors.fill: parent
            enabled: sw.enabled
            cursorShape: Qt.PointingHandCursor
            onClicked: sw.toggled(!sw.checked)
        }
    }

    component M3Slider: Slider {
        id: sl
        implicitHeight: 22

        background: Rectangle {
            x: sl.leftPadding
            y: sl.topPadding + sl.availableHeight / 2 - height / 2
            width: sl.availableWidth
            height: 6
            radius: 3
            color: Colors.cSurfaceContainerHighest

            Rectangle {
                width: sl.visualPosition * parent.width
                height: parent.height
                radius: 3
                color: Colors.cPrimary
            }
        }

        handle: Rectangle {
            x: sl.leftPadding + sl.visualPosition * (sl.availableWidth - width)
            y: sl.topPadding + sl.availableHeight / 2 - height / 2
            width: 16
            height: 16
            radius: Math.max(2, Colors.smallRadius - 2)
            color: sl.pressed ? Colors.cOnPrimaryContainer : Colors.cPrimary
            border.width: 2
            border.color: Colors.cSurface

            Behavior on scale { NumberAnimation { duration: 140; easing.type: Easing.OutCubic } }
            scale: sl.pressed ? 1.14 : 1.0
        }
    }

    Variants {
        model: Quickshell.screens

        PanelWindow {
            id: bar
            required property var modelData
            screen: modelData

            anchors {
                top: true
                left: true
                right: true
            }

            implicitHeight: 36
            color: Colors.cSurface

            WlrLayershell.layer: WlrLayer.Top
            WlrLayershell.namespace: "fasdeqos-bar"

            Item {
                anchors.fill: parent
                anchors.leftMargin: 10
                anchors.rightMargin: 10

                MouseArea {
                    anchors.fill: parent
                    acceptedButtons: Qt.NoButton
                    onWheel: wheel => {
                        root.niriAction([wheel.angleDelta.y > 0 ? "focus-column-left" : "focus-column-right"])
                    }
                }

                Row {
                    anchors.left: parent.left
                    anchors.verticalCenter: parent.verticalCenter
                    spacing: 10

                    Rectangle {
                        width: 28
                        height: 28
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: popups.launcherVisible ? Colors.cPrimaryContainer : (launchHover.hovered ? Colors.cSurfaceContainerHigh : "transparent")

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: launchHover }

                        Rectangle {
                            anchors.centerIn: parent
                            width: 16
                            height: 16
                            radius: 8
                            color: "transparent"
                            border.width: 2.2
                            border.color: popups.launcherVisible ? Colors.cOnPrimaryContainer : Colors.cPrimary

                            Behavior on border.color { ColorAnimation { duration: 180 } }
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: {
                                root.closeMenus()
                                settingsWindow.close()
                                popups.toggleLauncher()
                            }
                        }
                    }

                    Rectangle {
                        visible: Colors.showWorkspaces
                        width: workspaceRow.implicitWidth + 8
                        height: 26
                        radius: Math.min(13, Colors.uiRadius + 4)
                        anchors.verticalCenter: parent.verticalCenter
                        color: Colors.cBackground
                        border.width: 1
                        border.color: Colors.cOutlineVariant

                        Behavior on width { NumberAnimation { duration: 240; easing.type: Easing.OutExpo } }

                        MouseArea {
                            anchors.fill: parent
                            acceptedButtons: Qt.NoButton
                            onWheel: wheel => {
                                wheel.accepted = true
                                root.niriAction([wheel.angleDelta.y > 0 ? "focus-workspace-up" : "focus-workspace-down"])
                            }
                        }

                        Row {
                            id: workspaceRow
                            anchors.centerIn: parent
                            spacing: 4

                            Repeater {
                                model: {
                                    let list = []
                                    let all = root.niriWorkspaces || []
                                    for (let i = 0; i < all.length; i++) {
                                        let ws = all[i]
                                        if (ws && ws.output === bar.screen.name)
                                            list.push(ws)
                                    }
                                    list.sort((a, b) => a.idx - b.idx)
                                    return list
                                }

                                delegate: Rectangle {
                                    required property var modelData
                                    property bool selected: modelData.is_active === true

                                    width: selected ? 38 : 20
                                    height: 20
                                    radius: Math.min(10, Colors.smallRadius + 3)
                                    anchors.verticalCenter: parent.verticalCenter
                                    color: selected ? Colors.cPrimary : (wsHover.hovered ? Colors.cSurfaceContainerHighest : Colors.cSurfaceContainer)

                                    Behavior on width { NumberAnimation { duration: 260; easing.type: Easing.OutExpo } }
                                    Behavior on color { ColorAnimation { duration: 180 } }

                                    HoverHandler { id: wsHover }

                                    Text {
                                        anchors.centerIn: parent
                                        text: String(modelData.idx)
                                        color: selected ? Colors.cOnPrimary : Colors.cOnSurfaceVariant
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 10
                                        font.weight: selected ? Font.Bold : Font.Medium
                                    }

                                    MouseArea {
                                        anchors.fill: parent
                                        cursorShape: Qt.PointingHandCursor
                                        onClicked: root.niriAction(["focus-workspace", String(modelData.idx)])
                                        onWheel: wheel => {
                                            wheel.accepted = true
                                            root.niriAction([wheel.angleDelta.y > 0 ? "focus-workspace-up" : "focus-workspace-down"])
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                Rectangle {
                    visible: Colors.showClock
                    anchors.centerIn: parent
                    width: clockText.implicitWidth + 18
                    height: 26
                    radius: Colors.smallRadius
                    color: root.calendarMenu ? Colors.cPrimaryContainer : (clockHover.hovered ? Colors.cSurfaceContainerHigh : "transparent")

                    Behavior on color { ColorAnimation { duration: 180 } }
                    HoverHandler { id: clockHover }

                    Text {
                        id: clockText
                        anchors.centerIn: parent
                        text: root.currentDate
                        color: root.calendarMenu ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                        font.family: Colors.cFontFamily
                        font.pixelSize: 12
                        font.weight: Font.DemiBold
                    }

                    MouseArea {
                        anchors.fill: parent
                        cursorShape: Qt.PointingHandCursor
                        onClicked: root.toggleMenu("calendar")
                    }
                }

                Row {
                    anchors.right: parent.right
                    anchors.verticalCenter: parent.verticalCenter
                    spacing: 8

                    Row {
                        visible: Colors.showTray && SystemTray.items.values.length > 0
                        anchors.verticalCenter: parent.verticalCenter
                        spacing: 8

                        Repeater {
                            model: SystemTray.items

                            delegate: Item {
                                id: trayItem
                                required property var modelData
                                width: 20
                                height: 24
                                anchors.verticalCenter: parent.verticalCenter

                                Image {
                                    anchors.centerIn: parent
                                    width: 17
                                    height: 17
                                    source: modelData.icon
                                    fillMode: Image.PreserveAspectFit
                                    smooth: true
                                }

                                MouseArea {
                                    anchors.fill: parent
                                    acceptedButtons: Qt.LeftButton | Qt.RightButton
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: mouse => {
                                        if (mouse.button === Qt.LeftButton) {
                                            modelData.activate()
                                        } else {
                                            let pos = trayItem.mapToItem(null, mouse.x, trayItem.height)
                                            if (modelData.hasMenu)
                                                modelData.display(bar, pos.x, pos.y)
                                            else
                                                modelData.secondaryActivate()
                                        }
                                    }
                                }
                            }
                        }
                    }

                    Rectangle {
                        visible: Colors.showLayout
                        width: kbLabel.implicitWidth + 12
                        height: 26
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: kbHover.hovered ? Colors.cSurfaceContainerHigh : "transparent"

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: kbHover }

                        Text {
                            id: kbLabel
                            anchors.centerIn: parent
                            text: root.currentLayoutShort
                            color: Colors.cSecondary
                            font.family: Colors.cFontFamily
                            font.pixelSize: 11
                            font.weight: Font.Bold
                            verticalAlignment: Text.AlignVCenter
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.niriAction(["switch-layout", "next"])
                        }
                    }

                    Rectangle {
                        visible: Colors.showScreenshot
                        width: 28
                        height: 26
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: root.screenshotMenu ? Colors.cPrimaryContainer : (ssHover.hovered ? Colors.cSurfaceContainerHigh : "transparent")

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: ssHover }

                        Text {
                            anchors.centerIn: parent
                            text: "󰄀"
                            color: root.screenshotMenu ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                            font.family: Colors.cFontFamily
                            font.pixelSize: 16
                            verticalAlignment: Text.AlignVCenter
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.toggleMenu("screenshot")
                        }
                    }

                    Rectangle {
                        visible: Colors.showWifi
                        width: 28
                        height: 26
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: root.wifiMenu ? Colors.cPrimaryContainer : (wifiHover.hovered ? Colors.cSurfaceContainerHigh : "transparent")

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: wifiHover }

                        Text {
                            anchors.centerIn: parent
                            text: root.ethernetConnected ? "󰈀" : (root.wifiAvailable ? (root.wifiEnabled ? "󰤨" : "󰤭") : "󰤮")
                            color: root.wifiMenu ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                            font.family: Colors.cFontFamily
                            font.pixelSize: 16
                            verticalAlignment: Text.AlignVCenter
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.toggleMenu("wifi")
                        }
                    }

                    Rectangle {
                        visible: Colors.showBluetooth
                        width: 28
                        height: 26
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: root.bluetoothMenu ? Colors.cPrimaryContainer : (btHover.hovered ? Colors.cSurfaceContainerHigh : "transparent")

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: btHover }

                        Text {
                            anchors.centerIn: parent
                            text: root.bluetoothEnabled ? "󰂯" : "󰂲"
                            color: root.bluetoothMenu ? Colors.cOnPrimaryContainer : (root.bluetoothEnabled ? Colors.cOnSurface : Colors.cInactive)
                            font.family: Colors.cFontFamily
                            font.pixelSize: 16
                            verticalAlignment: Text.AlignVCenter
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.toggleMenu("bluetooth")
                        }
                    }

                    Rectangle {
                        visible: Colors.showAudio
                        width: volRow.implicitWidth + 12
                        height: 26
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: root.audioMenu ? Colors.cPrimaryContainer : (volHover.hovered ? Colors.cSurfaceContainerHigh : "transparent")

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: volHover }

                        Row {
                            id: volRow
                            anchors.centerIn: parent
                            spacing: 5

                            Text {
                                anchors.verticalCenter: parent.verticalCenter
                                text: root.outputMuted ? "󰖁" : "󰕾"
                                color: root.audioMenu ? Colors.cOnPrimaryContainer : Colors.cPrimary
                                font.family: Colors.cFontFamily
                                font.pixelSize: 15
                                verticalAlignment: Text.AlignVCenter
                            }

                            Text {
                                anchors.verticalCenter: parent.verticalCenter
                                text: Math.round(root.outputVolume) + "%"
                                color: root.audioMenu ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                font.weight: Font.Medium
                                verticalAlignment: Text.AlignVCenter
                            }
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.toggleMenu("audio")
                            onWheel: wheel => {
                                wheel.accepted = true
                                if (!root.audioSink || !root.audioSink.audio) return
                                let value = root.audioSink.audio.volume
                                value += wheel.angleDelta.y > 0 ? 0.05 : -0.05
                                root.audioSink.audio.volume = Math.max(0, Math.min(1.5, value))
                            }
                        }
                    }

                    Rectangle {
                        width: 28
                        height: 26
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: settingsWindow.settingsVisible ? Colors.cPrimaryContainer : (setHover.hovered ? Colors.cSurfaceContainerHigh : "transparent")

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: setHover }

                        Text {
                            anchors.centerIn: parent
                            text: "󰒓"
                            color: settingsWindow.settingsVisible ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                            font.family: Colors.cFontFamily
                            font.pixelSize: 17
                            verticalAlignment: Text.AlignVCenter
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: {
                                root.closeMenus()
                                popups.closeLauncher()
                                popups.closePower()
                                settingsWindow.toggle()
                            }
                        }
                    }

                    Rectangle {
                        width: 28
                        height: 26
                        radius: Colors.smallRadius
                        anchors.verticalCenter: parent.verticalCenter
                        color: pwrHover.hovered ? Colors.cErrorContainer : "transparent"

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: pwrHover }

                        Text {
                            anchors.centerIn: parent
                            text: "⏻"
                            color: Colors.cError
                            font.family: Colors.cFontFamily
                            font.pixelSize: 16
                            verticalAlignment: Text.AlignVCenter
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: {
                                root.closeMenus()
                                settingsWindow.close()
                                popups.togglePower()
                            }
                        }
                    }
                }
            }

            PopupWindow {
                id: calendarPopup
                property real anim: root.calendarMenu ? 1 : 0
                Behavior on anim { NumberAnimation { duration: 260; easing.type: Easing.OutExpo } }

                visible: root.calendarMenu || anim > 0.01
                anchor.window: bar
                anchor.rect.x: Math.round((bar.width - width) / 2)
                anchor.rect.y: 42
                implicitWidth: 340
                implicitHeight: 330
                color: "transparent"

                Rectangle {
                    anchors.fill: parent
                    radius: Colors.uiRadius
                    color: Colors.cSurface
                    border.width: 1
                    border.color: Colors.cOutlineVariant
                    opacity: calendarPopup.anim
                    scale: 0.93 + 0.07 * calendarPopup.anim
                    transform: Translate { y: (1 - calendarPopup.anim) * -10 }

                    MouseArea {
                        anchors.fill: parent
                        acceptedButtons: Qt.NoButton
                        onWheel: wheel => {
                            if (wheel.angleDelta.y > 0) root.shiftMonth(-1)
                            else if (wheel.angleDelta.y < 0) root.shiftMonth(1)
                        }
                    }

                    ColumnLayout {
                        anchors.fill: parent
                        anchors.margins: 16
                        spacing: 12

                        RowLayout {
                            Layout.fillWidth: true

                            Rectangle {
                                width: 28
                                height: 28
                                radius: Colors.smallRadius
                                color: prevHover.hovered ? Colors.cSurfaceContainerHighest : Colors.cSurfaceContainer
                                Behavior on color { ColorAnimation { duration: 160 } }
                                HoverHandler { id: prevHover }

                                Text {
                                    anchors.centerIn: parent
                                    text: "‹"
                                    color: Colors.cPrimary
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 18
                                }

                                MouseArea {
                                    anchors.fill: parent
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: root.shiftMonth(-1)
                                }
                            }

                            Text {
                                Layout.fillWidth: true
                                horizontalAlignment: Text.AlignHCenter
                                text: Qt.formatDate(new Date(root.calYear, root.calMonth, 1), "MMMM yyyy")
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 14
                                font.bold: true
                            }

                            Rectangle {
                                width: 28
                                height: 28
                                radius: Colors.smallRadius
                                color: nextHover.hovered ? Colors.cSurfaceContainerHighest : Colors.cSurfaceContainer
                                Behavior on color { ColorAnimation { duration: 160 } }
                                HoverHandler { id: nextHover }

                                Text {
                                    anchors.centerIn: parent
                                    text: "›"
                                    color: Colors.cPrimary
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 18
                                }

                                MouseArea {
                                    anchors.fill: parent
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: root.shiftMonth(1)
                                }
                            }
                        }

                        GridLayout {
                            Layout.fillWidth: true
                            Layout.fillHeight: true
                            columns: 7
                            rowSpacing: 6
                            columnSpacing: 6

                            Repeater {
                                model: ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]
                                delegate: Text {
                                    required property var modelData
                                    Layout.fillWidth: true
                                    horizontalAlignment: Text.AlignHCenter
                                    text: modelData
                                    color: Colors.cOnSurfaceVariant
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 11
                                    font.bold: true
                                }
                            }

                            Repeater {
                                model: root.calendarDays(root.calYear, root.calMonth)
                                delegate: Rectangle {
                                    required property var modelData
                                    Layout.fillWidth: true
                                    Layout.preferredHeight: 34
                                    radius: Colors.smallRadius
                                    color: modelData.isToday ? Colors.cPrimary : (dayHover.hovered && modelData.day !== "" ? Colors.cPrimaryContainer : "transparent")
                                    border.width: dayHover.hovered && modelData.day !== "" && !modelData.isToday ? 1 : 0
                                    border.color: Colors.cPrimary
                                    scale: dayHover.hovered && modelData.day !== "" ? 1.08 : 1.0

                                    Behavior on color { ColorAnimation { duration: 160 } }
                                    Behavior on scale { NumberAnimation { duration: 180; easing.type: Easing.OutExpo } }

                                    HoverHandler { id: dayHover }

                                    Text {
                                        anchors.centerIn: parent
                                        text: modelData.day
                                        color: modelData.isToday ? Colors.cOnPrimary : (dayHover.hovered ? Colors.cOnPrimaryContainer : Colors.cOnSurface)
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 12
                                        font.bold: modelData.isToday || dayHover.hovered
                                    }
                                }
                            }
                        }
                    }
                }
            }

            PopupWindow {
                id: screenshotPopup
                property real anim: root.screenshotMenu ? 1 : 0
                Behavior on anim { NumberAnimation { duration: 240; easing.type: Easing.OutExpo } }

                visible: root.screenshotMenu || anim > 0.01
                anchor.window: bar
                anchor.rect.x: bar.width - width - 140
                anchor.rect.y: 42
                implicitWidth: 210
                implicitHeight: 156
                color: "transparent"

                Rectangle {
                    anchors.fill: parent
                    radius: Colors.uiRadius
                    color: Colors.cSurface
                    border.width: 1
                    border.color: Colors.cOutlineVariant
                    opacity: screenshotPopup.anim
                    scale: 0.93 + 0.07 * screenshotPopup.anim
                    transform: Translate { y: (1 - screenshotPopup.anim) * -10 }

                    ColumnLayout {
                        anchors.fill: parent
                        anchors.margins: 10
                        spacing: 6

                        Repeater {
                            model: [
                                { label: "Area", icon: "󰩭", action: "screenshot" },
                                { label: "Full Screen", icon: "󰹑", action: "screenshot-screen" },
                                { label: "Active Window", icon: "󰖯", action: "screenshot-window" }
                            ]

                            delegate: Rectangle {
                                required property var modelData
                                Layout.fillWidth: true
                                Layout.fillHeight: true
                                radius: Colors.smallRadius
                                color: ssItemHover.hovered ? Colors.cPrimaryContainer : Colors.cSurfaceContainer

                                Behavior on color { ColorAnimation { duration: 160 } }
                                HoverHandler { id: ssItemHover }

                                RowLayout {
                                    anchors.fill: parent
                                    anchors.leftMargin: 10
                                    anchors.rightMargin: 10
                                    spacing: 10

                                    Text {
                                        text: modelData.icon
                                        color: ssItemHover.hovered ? Colors.cOnPrimaryContainer : Colors.cPrimary
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 16
                                    }

                                    Text {
                                        text: modelData.label
                                        color: ssItemHover.hovered ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 11
                                        font.bold: true
                                        Layout.fillWidth: true
                                    }
                                }

                                MouseArea {
                                    anchors.fill: parent
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: {
                                        root.closeMenus()
                                        root.niriAction([modelData.action])
                                    }
                                }
                            }
                        }
                    }
                }
            }

            PopupWindow {
                id: wifiPopup
                property real anim: root.wifiMenu ? 1 : 0
                Behavior on anim { NumberAnimation { duration: 260; easing.type: Easing.OutExpo } }

                visible: root.wifiMenu || anim > 0.01
                anchor.window: bar
                anchor.rect.x: bar.width - width - 110
                anchor.rect.y: 42
                implicitWidth: 310
                implicitHeight: 410
                color: "transparent"

                Rectangle {
                    anchors.fill: parent
                    radius: Colors.uiRadius
                    color: Colors.cSurface
                    border.width: 1
                    border.color: Colors.cOutlineVariant
                    opacity: wifiPopup.anim
                    scale: 0.93 + 0.07 * wifiPopup.anim
                    transform: Translate { y: (1 - wifiPopup.anim) * -10 }

                    ColumnLayout {
                        anchors.fill: parent
                        anchors.margins: 14
                        spacing: 10

                        RowLayout {
                            Layout.fillWidth: true

                            Text {
                                text: "Network"
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 15
                                font.bold: true
                                Layout.fillWidth: true
                            }
                        }

                        Rectangle {
                            Layout.fillWidth: true
                            Layout.preferredHeight: 3
                            radius: 1.5
                            color: Colors.cSurfaceContainerHighest
                            visible: root.wifiBusy
                            clip: true

                            Rectangle {
                                id: busyBar
                                width: parent.width * 0.4
                                height: parent.height
                                radius: 1.5
                                color: Colors.cPrimary

                                SequentialAnimation on x {
                                    running: root.wifiBusy
                                    loops: Animation.Infinite
                                    NumberAnimation { from: -busyBar.width; to: busyBar.parent.width; duration: 900; easing.type: Easing.InOutQuad }
                                }
                            }
                        }

                        RowLayout {
                            Layout.fillWidth: true
                            visible: root.ethernetDevice.length > 0

                            Text {
                                text: "󰈀  Ethernet"
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 12
                                Layout.fillWidth: true
                            }

                            M3Switch {
                                checked: root.ethernetConnected
                                enabled: !root.wifiBusy
                                onToggled: root.toggleEthernet()
                            }
                        }

                        RowLayout {
                            Layout.fillWidth: true
                            visible: root.wifiAvailable

                            Text {
                                text: "󰤨  Wi-Fi"
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 12
                                Layout.fillWidth: true
                            }

                            M3Switch {
                                checked: root.wifiEnabled
                                enabled: !root.wifiBusy
                                onToggled: root.toggleWifi()
                            }
                        }

                        Rectangle {
                            Layout.fillWidth: true
                            Layout.preferredHeight: 34
                            radius: Colors.smallRadius
                            visible: root.wifiAvailable && root.wifiEnabled
                            color: scanBtnHover.hovered ? Colors.cPrimaryContainer : Colors.cSurfaceContainerHigh
                            Behavior on color { ColorAnimation { duration: 160 } }
                            HoverHandler { id: scanBtnHover }

                            RowLayout {
                                anchors.fill: parent
                                anchors.leftMargin: 10
                                anchors.rightMargin: 10

                                Text {
                                    text: "󰍉"
                                    color: scanBtnHover.hovered ? Colors.cOnPrimaryContainer : Colors.cPrimary
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 15
                                }

                                Text {
                                    Layout.fillWidth: true
                                    text: root.wifiBusy ? "Working..." : "Scan networks"
                                    color: scanBtnHover.hovered ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 10
                                }
                            }

                            MouseArea {
                                anchors.fill: parent
                                enabled: !root.wifiBusy
                                cursorShape: Qt.PointingHandCursor
                                onClicked: root.scanWifi()
                            }
                        }

                        ListView {
                            Layout.fillWidth: true
                            Layout.fillHeight: true
                            clip: true
                            spacing: 5
                            visible: root.wifiAvailable
                            model: root.wifiEnabled ? root.wifiNetworks : []

                            delegate: Rectangle {
                                required property var modelData
                                width: ListView.view.width
                                height: 40
                                radius: Colors.smallRadius
                                color: modelData.connected ? Colors.cPrimaryContainer : (wItemHover.hovered ? Colors.cSurfaceContainerHigh : Colors.cSurfaceContainer)
                                Behavior on color { ColorAnimation { duration: 150 } }
                                HoverHandler { id: wItemHover }

                                RowLayout {
                                    anchors.fill: parent
                                    anchors.leftMargin: 10
                                    anchors.rightMargin: 10

                                    Text {
                                        text: "󰤨"
                                        color: modelData.connected ? Colors.cOnPrimaryContainer : Colors.cPrimary
                                        font.family: Colors.cFontFamily
                                    }

                                    Text {
                                        Layout.fillWidth: true
                                        text: modelData.ssid
                                        color: modelData.connected ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 10
                                        elide: Text.ElideRight
                                    }

                                    Text {
                                        text: modelData.signal + "%"
                                        color: modelData.connected ? Colors.cOnPrimaryContainer : Colors.cOnSurfaceVariant
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 9
                                    }
                                }

                                MouseArea {
                                    anchors.fill: parent
                                    enabled: root.wifiEnabled && !root.wifiBusy
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: root.connectWifi(modelData.ssid)
                                }
                            }
                        }

                        Text {
                            Layout.fillWidth: true
                            visible: root.wifiAvailable && (!root.wifiEnabled || root.wifiNetworks.length === 0)
                            text: root.wifiEnabled ? "No networks found" : "Wi-Fi is turned off"
                            color: Colors.cInactive
                            font.family: Colors.cFontFamily
                            font.pixelSize: 10
                            horizontalAlignment: Text.AlignHCenter
                        }
                    }
                }
            }

            PopupWindow {
                id: bluetoothPopup
                property real anim: root.bluetoothMenu ? 1 : 0
                Behavior on anim { NumberAnimation { duration: 260; easing.type: Easing.OutExpo } }

                visible: root.bluetoothMenu || anim > 0.01
                anchor.window: bar
                anchor.rect.x: bar.width - width - 70
                anchor.rect.y: 42
                implicitWidth: 300
                implicitHeight: 330
                color: "transparent"

                Rectangle {
                    anchors.fill: parent
                    radius: Colors.uiRadius
                    color: Colors.cSurface
                    border.width: 1
                    border.color: Colors.cOutlineVariant
                    opacity: bluetoothPopup.anim
                    scale: 0.93 + 0.07 * bluetoothPopup.anim
                    transform: Translate { y: (1 - bluetoothPopup.anim) * -10 }

                    ColumnLayout {
                        anchors.fill: parent
                        anchors.margins: 14
                        spacing: 10

                        RowLayout {
                            Layout.fillWidth: true

                            Text {
                                text: "Bluetooth"
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 15
                                font.bold: true
                            }

                            Item { Layout.fillWidth: true }

                            M3Switch {
                                checked: root.bluetoothEnabled
                                onToggled: root.toggleBluetooth()
                            }
                        }

                        ListView {
                            Layout.fillWidth: true
                            Layout.fillHeight: true
                            clip: true
                            spacing: 5
                            model: root.bluetoothDevices

                            delegate: Rectangle {
                                required property var modelData
                                width: ListView.view.width
                                height: 40
                                radius: Colors.smallRadius
                                color: bItemHover.hovered ? Colors.cSurfaceContainerHigh : Colors.cSurfaceContainer
                                Behavior on color { ColorAnimation { duration: 150 } }
                                HoverHandler { id: bItemHover }

                                RowLayout {
                                    anchors.fill: parent
                                    anchors.leftMargin: 10
                                    anchors.rightMargin: 10

                                    Text {
                                        text: "󰂯"
                                        color: Colors.cPrimary
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 16
                                    }

                                    Text {
                                        Layout.fillWidth: true
                                        text: modelData.name
                                        color: Colors.cOnSurface
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 10
                                        elide: Text.ElideRight
                                    }

                                    Text {
                                        text: "→"
                                        color: Colors.cPrimary
                                    }
                                }

                                MouseArea {
                                    anchors.fill: parent
                                    enabled: root.bluetoothEnabled
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: root.connectBluetooth(modelData.address)
                                }
                            }
                        }

                        Text {
                            visible: root.bluetoothDevices.length === 0
                            text: "No paired devices"
                            color: Colors.cInactive
                            font.family: Colors.cFontFamily
                            font.pixelSize: 10
                        }
                    }
                }
            }

            PopupWindow {
                id: audioPopup
                property real anim: root.audioMenu ? 1 : 0
                Behavior on anim { NumberAnimation { duration: 260; easing.type: Easing.OutExpo } }

                visible: root.audioMenu || anim > 0.01
                anchor.window: bar
                anchor.rect.x: bar.width - width - 16
                anchor.rect.y: 42
                implicitWidth: 340
                implicitHeight: 400
                color: "transparent"

                Rectangle {
                    anchors.fill: parent
                    radius: Colors.uiRadius
                    color: Colors.cSurface
                    border.width: 1
                    border.color: Colors.cOutlineVariant
                    opacity: audioPopup.anim
                    scale: 0.93 + 0.07 * audioPopup.anim
                    transform: Translate { y: (1 - audioPopup.anim) * -10 }

                    ColumnLayout {
                        anchors.fill: parent
                        anchors.margins: 14
                        spacing: 10

                        RowLayout {
                            Layout.fillWidth: true

                            Text {
                                text: "Sound & Audio"
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 15
                                font.bold: true
                                Layout.fillWidth: true
                            }

                            Text {
                                text: "✕"
                                color: Colors.cOnSurfaceVariant
                                font.family: Colors.cFontFamily
                                font.pixelSize: 14
                                MouseArea {
                                    anchors.fill: parent
                                    anchors.margins: -6
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: root.closeMenus()
                                }
                            }
                        }

                        RowLayout {
                            Layout.fillWidth: true
                            Text {
                                text: "󰕾  Output"
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                Layout.fillWidth: true
                            }
                            Text {
                                text: Math.round(root.outputVolume) + "%"
                                color: Colors.cPrimary
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                font.bold: true
                            }
                        }

                        M3Slider {
                            Layout.fillWidth: true
                            from: 0
                            to: 150
                            value: root.outputVolume
                            enabled: !!root.audioSink && !!root.audioSink.audio

                            onMoved: {
                                if (root.audioSink && root.audioSink.audio)
                                    root.audioSink.audio.volume = value / 100
                            }
                        }

                        RowLayout {
                            Layout.fillWidth: true

                            Text {
                                Layout.fillWidth: true
                                text: root.audioSink ? (root.audioSink.description || root.audioSink.name) : "No audio output"
                                color: Colors.cOnSurfaceVariant
                                font.family: Colors.cFontFamily
                                font.pixelSize: 9
                                elide: Text.ElideRight
                            }

                            M3Switch {
                                checked: !root.outputMuted
                                enabled: !!root.audioSink && !!root.audioSink.audio
                                onToggled: val => root.audioSink.audio.muted = !val
                            }
                        }

                        Rectangle {
                            Layout.fillWidth: true
                            height: 1
                            color: Colors.cOutlineVariant
                        }

                        RowLayout {
                            Layout.fillWidth: true
                            Text {
                                text: "󰍬  Microphone"
                                color: Colors.cOnSurface
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                Layout.fillWidth: true
                            }
                            Text {
                                text: Math.round(root.inputVolume) + "%"
                                color: Colors.cPrimary
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                font.bold: true
                            }
                        }

                        M3Slider {
                            Layout.fillWidth: true
                            from: 0
                            to: 150
                            value: root.inputVolume
                            enabled: !!root.audioSource && !!root.audioSource.audio

                            onMoved: {
                                if (root.audioSource && root.audioSource.audio)
                                    root.audioSource.audio.volume = value / 100
                            }
                        }

                        RowLayout {
                            Layout.fillWidth: true

                            Text {
                                Layout.fillWidth: true
                                text: root.audioSource ? (root.audioSource.description || root.audioSource.name) : "No microphone"
                                color: Colors.cOnSurfaceVariant
                                font.family: Colors.cFontFamily
                                font.pixelSize: 9
                                elide: Text.ElideRight
                            }

                            M3Switch {
                                checked: !root.inputMuted
                                enabled: !!root.audioSource && !!root.audioSource.audio
                                onToggled: val => root.audioSource.audio.muted = !val
                            }
                        }

                        Rectangle {
                            Layout.fillWidth: true
                            height: 1
                            color: Colors.cOutlineVariant
                        }

                        Text {
                            text: "Output devices"
                            color: Colors.cOnSurfaceVariant
                            font.family: Colors.cFontFamily
                            font.pixelSize: 10
                        }

                        ListView {
                            Layout.fillWidth: true
                            Layout.fillHeight: true
                            clip: true
                            spacing: 5
                            model: Pipewire.nodes.values.filter(node => node.isSink && !node.isStream)

                            delegate: Rectangle {
                                required property var modelData
                                property bool isCurrent: root.audioSink && root.audioSink.id === modelData.id
                                width: ListView.view.width
                                height: 36
                                radius: Colors.smallRadius
                                color: isCurrent ? Colors.cPrimaryContainer : (sinkItemHover.hovered ? Colors.cSurfaceContainerHigh : Colors.cSurfaceContainer)

                                Behavior on color { ColorAnimation { duration: 150 } }
                                HoverHandler { id: sinkItemHover }

                                RowLayout {
                                    anchors.fill: parent
                                    anchors.leftMargin: 10
                                    anchors.rightMargin: 10

                                    Text {
                                        text: "󰓃"
                                        color: isCurrent ? Colors.cOnPrimaryContainer : Colors.cPrimary
                                        font.family: Colors.cFontFamily
                                    }

                                    Text {
                                        Layout.fillWidth: true
                                        text: modelData.description || modelData.name
                                        color: isCurrent ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 9
                                        elide: Text.ElideRight
                                    }

                                    Text {
                                        visible: isCurrent
                                        text: "✓"
                                        color: Colors.cOnPrimaryContainer
                                    }
                                }

                                MouseArea {
                                    anchors.fill: parent
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: Pipewire.preferredDefaultAudioSink = modelData
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
EOF_QS_SHELL_QML
chmod 644 /usr/share/fasdeqos/quickshell/shell.qml
cat >/usr/share/fasdeqos/quickshell/Colors.qml <<'EOF_QS_COLORS_QML'
pragma Singleton
import QtQuick
import Quickshell
import Quickshell.Io

QtObject {
    id: colorsRoot

    property bool settingsLoaded: false

    property string currentTheme: "mono"
    property int uiRadius: 8
    readonly property int smallRadius: Math.max(2, Math.round(uiRadius * 0.65))
    property int launcherWidth: 580
    property int launcherHeight: 520

    property bool showWorkspaces: true
    property bool showClock: true
    property bool showTray: true
    property bool showLayout: true
    property bool showWifi: true
    property bool showBluetooth: true
    property bool showAudio: true
    property bool showScreenshot: true

    readonly property var themeList: [
        { "id": "mono", "name": "Mono", "preview": "#E6E6E6" },
        { "id": "sunset", "name": "Sunset", "preview": "#FF713D" },
        { "id": "crimson", "name": "Crimson", "preview": "#FF5277" },
        { "id": "emerald", "name": "Emerald", "preview": "#4CD98B" },
        { "id": "ocean", "name": "Ocean", "preview": "#5CB8FF" },
        { "id": "amethyst", "name": "Amethyst", "preview": "#B388FF" }
    ]

    property Timer saveTimer: Timer {
        interval: 250
        repeat: false
        onTriggered: colorsRoot.writeSettings()
    }

    property Process loadProc: Process {
        command: ["bash", "-c", "cat \"\$HOME/.config/quickshell/settings.json\" 2>/dev/null || echo '{}'"]
        stdout: StdioCollector {
            onStreamFinished: {
                try {
                    let data = JSON.parse(text.trim() || "{}")
                    if (typeof data.currentTheme === "string") colorsRoot.currentTheme = data.currentTheme
                    if (typeof data.uiRadius === "number") colorsRoot.uiRadius = data.uiRadius
                    if (typeof data.launcherWidth === "number") colorsRoot.launcherWidth = data.launcherWidth
                    if (typeof data.launcherHeight === "number") colorsRoot.launcherHeight = data.launcherHeight
                    if (typeof data.showWorkspaces === "boolean") colorsRoot.showWorkspaces = data.showWorkspaces
                    if (typeof data.showClock === "boolean") colorsRoot.showClock = data.showClock
                    if (typeof data.showTray === "boolean") colorsRoot.showTray = data.showTray
                    if (typeof data.showLayout === "boolean") colorsRoot.showLayout = data.showLayout
                    if (typeof data.showWifi === "boolean") colorsRoot.showWifi = data.showWifi
                    if (typeof data.showBluetooth === "boolean") colorsRoot.showBluetooth = data.showBluetooth
                    if (typeof data.showAudio === "boolean") colorsRoot.showAudio = data.showAudio
                    if (typeof data.showScreenshot === "boolean") colorsRoot.showScreenshot = data.showScreenshot
                } catch (e) {}
                colorsRoot.settingsLoaded = true
                colorsRoot.syncNiriColors()
            }
        }
    }

    function scheduleSave() {
        if (settingsLoaded)
            saveTimer.restart()
    }

    function writeSettings() {
        let obj = {
            "currentTheme": currentTheme,
            "uiRadius": uiRadius,
            "launcherWidth": launcherWidth,
            "launcherHeight": launcherHeight,
            "showWorkspaces": showWorkspaces,
            "showClock": showClock,
            "showTray": showTray,
            "showLayout": showLayout,
            "showWifi": showWifi,
            "showBluetooth": showBluetooth,
            "showAudio": showAudio,
            "showScreenshot": showScreenshot
        }
        let jsonStr = JSON.stringify(obj, null, 2)
        let script = "mkdir -p \"$HOME/.config/quickshell\" && cat << 'EOF' > \"$HOME/.config/quickshell/settings.json\"\n" + jsonStr + "\nEOF\n"
        Quickshell.execDetached(["bash", "-c", script])
    }

    function paletteFor(theme) {
        if (theme === "sunset") {
            return {
                "bg": "#160D0B", "surf": "#21130F", "cont": "#2B1913", "high": "#382018", "highest": "#48271C", "variant": "#593125",
                "pri": "#FF713D", "priDim": "#E9582D", "priCont": "#78321F", "onPri": "#2C0D05", "onPriCont": "#FFD5C4",
                "sec": "#FFA17D", "secCont": "#653727", "ter": "#FFBD70", "terCont": "#63401F",
                "err": "#FF5449", "errCont": "#70251F", "onBg": "#FFE0D3", "onSurf": "#FFE0D3", "onSurfVar": "#D9AC98",
                "out": "#8C5743", "outVar": "#503126", "inact": "#9C7160"
            }
        }
        if (theme === "crimson") {
            return {
                "bg": "#160B0E", "surf": "#211015", "cont": "#2C161D", "high": "#391D26", "highest": "#492430", "variant": "#5A2E3C",
                "pri": "#FF5277", "priDim": "#E03E63", "priCont": "#7A1F38", "onPri": "#2E0712", "onPriCont": "#FFD6DF",
                "sec": "#FF94AA", "secCont": "#662839", "ter": "#FFB27D", "terCont": "#63381F",
                "err": "#FF5449", "errCont": "#70251F", "onBg": "#FFE0E6", "onSurf": "#FFE0E6", "onSurfVar": "#D9A8B3",
                "out": "#8C4D5D", "outVar": "#502A34", "inact": "#9C6B77"
            }
        }
        if (theme === "emerald") {
            return {
                "bg": "#0B1510", "surf": "#112018", "cont": "#172B20", "high": "#1E382A", "highest": "#264735", "variant": "#305943",
                "pri": "#4CD98B", "priDim": "#36B871", "priCont": "#175C37", "onPri": "#052614", "onPriCont": "#C8F7DC",
                "sec": "#8CE6B4", "secCont": "#224F37", "ter": "#A3D977", "terCont": "#385222",
                "err": "#FF5449", "errCont": "#70251F", "onBg": "#DCF5E7", "onSurf": "#DCF5E7", "onSurfVar": "#A3CCB5",
                "out": "#4D8065", "outVar": "#2A4A39", "inact": "#6B947E"
            }
        }
        if (theme === "ocean") {
            return {
                "bg": "#0B1117", "surf": "#101A24", "cont": "#162432", "high": "#1D2F42", "highest": "#253C54", "variant": "#2F4C69",
                "pri": "#5CB8FF", "priDim": "#3D9CE6", "priCont": "#1A4B75", "onPri": "#051E33", "onPriCont": "#D1EBFF",
                "sec": "#94D1FF", "secCont": "#24435E", "ter": "#7CE0D3", "terCont": "#1F524C",
                "err": "#FF5449", "errCont": "#70251F", "onBg": "#DCEEFF", "onSurf": "#DCEEFF", "onSurfVar": "#A3C2DB",
                "out": "#4D6F8C", "outVar": "#2A4052", "inact": "#6B879E"
            }
        }
        if (theme === "amethyst") {
            return {
                "bg": "#110D17", "surf": "#1A1324", "cont": "#231A30", "high": "#2E2240", "highest": "#3B2C52", "variant": "#4A3766",
                "pri": "#B388FF", "priDim": "#9666EB", "priCont": "#4A2B80", "onPri": "#1E0942", "onPriCont": "#E8DCFF",
                "sec": "#CCB0FF", "secCont": "#3F2B63", "ter": "#F299D4", "terCont": "#5E2B4D",
                "err": "#FF5449", "errCont": "#70251F", "onBg": "#ECE3FF", "onSurf": "#ECE3FF", "onSurfVar": "#C2B2DB",
                "out": "#6D598C", "outVar": "#3E3152", "inact": "#85749E"
            }
        }
        return {
            "bg": "#0E0E0E", "surf": "#161616", "cont": "#1F1F1F", "high": "#2A2A2A", "highest": "#363636", "variant": "#424242",
            "pri": "#F2F2F2", "priDim": "#CCCCCC", "priCont": "#3A3A3A", "onPri": "#111111", "onPriCont": "#FFFFFF",
            "sec": "#BDBDBD", "secCont": "#2E2E2E", "ter": "#9E9E9E", "terCont": "#282828",
            "err": "#FF5449", "errCont": "#521E1B", "onBg": "#F0F0F0", "onSurf": "#F0F0F0", "onSurfVar": "#A8A8A8",
            "out": "#666666", "outVar": "#333333", "inact": "#777777"
        }
    }

    function syncNiriColors() {
        let pal = paletteFor(currentTheme)
        let script = "mkdir -p \"$HOME/.config/niri\" && cat << 'EOF' > \"$HOME/.config/niri/colors.kdl\"\n" +
                     "layout {\n" +
                     "    focus-ring {\n" +
                     "        active-color \"" + pal.pri + "\"\n" +
                     "        inactive-color \"" + pal.outVar + "\"\n" +
                     "    }\n" +
                     "    border {\n" +
                     "        active-color \"" + pal.pri + "\"\n" +
                     "        inactive-color \"" + pal.outVar + "\"\n" +
                     "    }\n" +
                     "}\n" +
                     "EOF\n" +
                     "niri msg action load-config-file >/dev/null 2>&1 || touch \"\$HOME/.config/niri/config.kdl\"\n"
        Quickshell.execDetached(["bash", "-c", script])
    }

    onCurrentThemeChanged: {
        if (settingsLoaded) {
            syncNiriColors()
            scheduleSave()
        }
    }
    onUiRadiusChanged: scheduleSave()
    onLauncherWidthChanged: scheduleSave()
    onLauncherHeightChanged: scheduleSave()
    onShowWorkspacesChanged: scheduleSave()
    onShowClockChanged: scheduleSave()
    onShowTrayChanged: scheduleSave()
    onShowLayoutChanged: scheduleSave()
    onShowWifiChanged: scheduleSave()
    onShowBluetoothChanged: scheduleSave()
    onShowAudioChanged: scheduleSave()
    onShowScreenshotChanged: scheduleSave()

    Component.onCompleted: {
        loadProc.running = true
    }

    readonly property var p: paletteFor(currentTheme)

    readonly property color cBackground: p.bg
    readonly property color cSurface: p.surf
    readonly property color cSurfaceContainer: p.cont
    readonly property color cSurfaceContainerHigh: p.high
    readonly property color cSurfaceContainerHighest: p.highest
    readonly property color cSurfaceVariant: p.variant

    readonly property color cPrimary: p.pri
    readonly property color cPrimaryDim: p.priDim
    readonly property color cPrimaryContainer: p.priCont
    readonly property color cOnPrimary: p.onPri
    readonly property color cOnPrimaryContainer: p.onPriCont

    readonly property color cSecondary: p.sec
    readonly property color cSecondaryContainer: p.secCont
    readonly property color cTertiary: p.ter
    readonly property color cTertiaryContainer: p.terCont

    readonly property color cError: p.err
    readonly property color cErrorContainer: p.errCont

    readonly property color cOnBackground: p.onBg
    readonly property color cOnSurface: p.onSurf
    readonly property color cOnSurfaceVariant: p.onSurfVar

    readonly property color cOutline: p.out
    readonly property color cOutlineVariant: p.outVar

    readonly property color cOverlay: "#B3000000"

    readonly property color cActive: p.pri
    readonly property color cInactive: p.inact
    readonly property color cSuccess: "#C5D99A"

    readonly property string cFontFamily: "JetBrainsMono Nerd Font"
}
EOF_QS_COLORS_QML
chmod 644 /usr/share/fasdeqos/quickshell/Colors.qml
cat >/usr/share/fasdeqos/quickshell/Settings.qml <<'EOF_QS_SETTINGS_QML'
import QtQuick
import QtQuick.Controls
import QtQuick.Layouts
import Quickshell
import Quickshell.Wayland

PanelWindow {
    id: root

    property bool settingsVisible: false

    function open() {
        settingsVisible = true
        Qt.callLater(function() {
            focusRoot.forceActiveFocus()
        })
    }

    function close() {
        settingsVisible = false
    }

    function toggle() {
        if (settingsVisible) close()
        else open()
    }

    anchors {
        top: true
        bottom: true
        left: true
        right: true
    }

    property real cardAnim: settingsVisible ? 1 : 0
    Behavior on cardAnim {
        NumberAnimation { duration: 260; easing.type: Easing.OutExpo }
    }

    visible: settingsVisible || cardAnim > 0.01
    color: "transparent"
    exclusionMode: ExclusionMode.Ignore
    WlrLayershell.layer: WlrLayer.Overlay
    WlrLayershell.keyboardFocus: settingsVisible ? WlrKeyboardFocus.Exclusive : WlrKeyboardFocus.None
    WlrLayershell.namespace: "fasdeqos-settings"

    Item {
        id: focusRoot
        anchors.fill: parent
        focus: root.settingsVisible

        Keys.onEscapePressed: root.close()

        Rectangle {
            anchors.fill: parent
            color: Colors.cOverlay
            opacity: root.cardAnim

            MouseArea {
                anchors.fill: parent
                onClicked: root.close()
            }
        }

        Rectangle {
            width: 500
            height: 560
            radius: Colors.uiRadius
            anchors.centerIn: parent
            color: Colors.cSurface
            border.width: 1
            border.color: Colors.cOutlineVariant
            opacity: root.cardAnim
            scale: 0.93 + 0.07 * root.cardAnim
            transform: Translate { y: (1 - root.cardAnim) * 14 }

            MouseArea {
                anchors.fill: parent
            }

            ColumnLayout {
                anchors.fill: parent
                anchors.margins: 20
                spacing: 14

                RowLayout {
                    Layout.fillWidth: true

                    Text {
                        text: "Settings"
                        color: Colors.cOnSurface
                        font.family: Colors.cFontFamily
                        font.pixelSize: 17
                        font.weight: Font.Bold
                        Layout.fillWidth: true
                    }

                    Rectangle {
                        width: 28
                        height: 28
                        radius: Colors.smallRadius
                        color: closeHover.hovered ? Colors.cSurfaceContainerHighest : Colors.cSurfaceContainer

                        Behavior on color { ColorAnimation { duration: 180 } }
                        HoverHandler { id: closeHover }

                        Text {
                            anchors.centerIn: parent
                            text: "✕"
                            color: Colors.cOnSurfaceVariant
                            font.family: Colors.cFontFamily
                            font.pixelSize: 12
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.close()
                        }
                    }
                }

                Flickable {
                    Layout.fillWidth: true
                    Layout.fillHeight: true
                    contentWidth: width
                    contentHeight: settingsCol.implicitHeight
                    clip: true

                    ColumnLayout {
                        id: settingsCol
                        width: parent.width
                        spacing: 14

                        ColumnLayout {
                            Layout.fillWidth: true
                            spacing: 8

                            Text {
                                text: "Color Scheme"
                                color: Colors.cOnSurfaceVariant
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                font.weight: Font.DemiBold
                            }

                            RowLayout {
                                Layout.fillWidth: true
                                spacing: 6

                                Repeater {
                                    model: Colors.themeList

                                    delegate: Rectangle {
                                        required property var modelData
                                        property bool selected: Colors.currentTheme === modelData.id

                                        Layout.fillWidth: true
                                        Layout.preferredHeight: 54
                                        radius: Colors.smallRadius
                                        color: selected ? Colors.cPrimaryContainer : (thHover.hovered ? Colors.cSurfaceContainerHigh : Colors.cSurfaceContainer)
                                        border.width: selected ? 2 : 1
                                        border.color: selected ? Colors.cPrimary : Colors.cOutlineVariant

                                        Behavior on color { ColorAnimation { duration: 200 } }
                                        Behavior on border.color { ColorAnimation { duration: 200 } }
                                        HoverHandler { id: thHover }

                                        ColumnLayout {
                                            anchors.centerIn: parent
                                            spacing: 5

                                            Rectangle {
                                                Layout.alignment: Qt.AlignHCenter
                                                width: 16
                                                height: 16
                                                radius: Math.min(8, Colors.smallRadius)
                                                color: modelData.preview
                                            }

                                            Text {
                                                Layout.alignment: Qt.AlignHCenter
                                                text: modelData.name
                                                color: selected ? Colors.cOnPrimaryContainer : Colors.cOnSurface
                                                font.family: Colors.cFontFamily
                                                font.pixelSize: 9
                                                font.bold: selected
                                            }
                                        }

                                        MouseArea {
                                            anchors.fill: parent
                                            cursorShape: Qt.PointingHandCursor
                                            onClicked: Colors.currentTheme = modelData.id
                                        }
                                    }
                                }
                            }
                        }

                        Rectangle {
                            Layout.fillWidth: true
                            height: 1
                            color: Colors.cOutlineVariant
                        }

                        ColumnLayout {
                            Layout.fillWidth: true
                            spacing: 6

                            Text {
                                text: "Appearance & Sizing"
                                color: Colors.cOnSurfaceVariant
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                font.weight: Font.DemiBold
                            }

                            RowLayout {
                                Layout.fillWidth: true
                                Text {
                                    text: "Corner Radius"
                                    color: Colors.cOnSurface
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 10
                                    Layout.fillWidth: true
                                }
                                Text {
                                    text: Colors.uiRadius + "px"
                                    color: Colors.cPrimary
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 10
                                    font.bold: true
                                }
                            }

                            Slider {
                                Layout.fillWidth: true
                                from: 0
                                to: 24
                                stepSize: 1
                                value: Colors.uiRadius
                                onMoved: Colors.uiRadius = Math.round(value)
                            }

                            RowLayout {
                                Layout.fillWidth: true
                                Text {
                                    text: "Launcher Width"
                                    color: Colors.cOnSurface
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 10
                                    Layout.fillWidth: true
                                }
                                Text {
                                    text: Colors.launcherWidth + "px"
                                    color: Colors.cPrimary
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 10
                                    font.bold: true
                                }
                            }

                            Slider {
                                Layout.fillWidth: true
                                from: 420
                                to: 820
                                stepSize: 10
                                value: Colors.launcherWidth
                                onMoved: Colors.launcherWidth = Math.round(value)
                            }

                            RowLayout {
                                Layout.fillWidth: true
                                Text {
                                    text: "Launcher Height"
                                    color: Colors.cOnSurface
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 10
                                    Layout.fillWidth: true
                                }
                                Text {
                                    text: Colors.launcherHeight + "px"
                                    color: Colors.cPrimary
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 10
                                    font.bold: true
                                }
                            }

                            Slider {
                                Layout.fillWidth: true
                                from: 380
                                to: 720
                                stepSize: 10
                                value: Colors.launcherHeight
                                onMoved: Colors.launcherHeight = Math.round(value)
                            }
                        }

                        Rectangle {
                            Layout.fillWidth: true
                            height: 1
                            color: Colors.cOutlineVariant
                        }

                        ColumnLayout {
                            Layout.fillWidth: true
                            spacing: 6

                            Text {
                                text: "Bar Applets"
                                color: Colors.cOnSurfaceVariant
                                font.family: Colors.cFontFamily
                                font.pixelSize: 11
                                font.weight: Font.DemiBold
                            }

                            Repeater {
                                model: [
                                    { label: "Workspaces", key: "showWorkspaces" },
                                    { label: "Clock & Calendar", key: "showClock" },
                                    { label: "System Tray", key: "showTray" },
                                    { label: "Keyboard Layout", key: "showLayout" },
                                    { label: "Screenshot", key: "showScreenshot" },
                                    { label: "Wi-Fi / Network", key: "showWifi" },
                                    { label: "Bluetooth", key: "showBluetooth" },
                                    { label: "Audio", key: "showAudio" }
                                ]

                                delegate: Rectangle {
                                    required property var modelData
                                    property bool isOn: Colors[modelData.key]

                                    Layout.fillWidth: true
                                    Layout.preferredHeight: 38
                                    radius: Colors.smallRadius
                                    color: rowHover.hovered ? Colors.cSurfaceContainerHigh : Colors.cSurfaceContainer

                                    Behavior on color { ColorAnimation { duration: 160 } }
                                    HoverHandler { id: rowHover }

                                    RowLayout {
                                        anchors.fill: parent
                                        anchors.leftMargin: 12
                                        anchors.rightMargin: 12

                                        Text {
                                            text: modelData.label
                                            color: Colors.cOnSurface
                                            font.family: Colors.cFontFamily
                                            font.pixelSize: 11
                                            Layout.fillWidth: true
                                        }

                                        Rectangle {
                                            width: 42
                                            height: 22
                                            radius: Colors.smallRadius
                                            color: isOn ? Colors.cPrimary : Colors.cSurfaceContainerHighest
                                            border.width: 1
                                            border.color: isOn ? Colors.cPrimary : Colors.cOutline

                                            Behavior on color { ColorAnimation { duration: 200 } }

                                            Rectangle {
                                                width: 16
                                                height: 16
                                                radius: Math.max(2, Colors.smallRadius - 2)
                                                anchors.verticalCenter: parent.verticalCenter
                                                x: isOn ? parent.width - width - 3 : 3
                                                color: isOn ? Colors.cOnPrimary : Colors.cOnSurfaceVariant

                                                Behavior on x { NumberAnimation { duration: 220; easing.type: Easing.OutExpo } }
                                            }

                                            MouseArea {
                                                anchors.fill: parent
                                                cursorShape: Qt.PointingHandCursor
                                                onClicked: Colors[modelData.key] = !Colors[modelData.key]
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
EOF_QS_SETTINGS_QML
chmod 644 /usr/share/fasdeqos/quickshell/Settings.qml
cat >/usr/share/fasdeqos/quickshell/Popups.qml <<'EOF_QS_POPUPS_QML'
import QtQuick
import QtQuick.Controls
import QtQuick.Layouts
import Quickshell
import Quickshell.Wayland

PanelWindow {
    id: root

    property bool launcherVisible: false
    property bool powerVisible: false
    property string searchText: ""
    property int selectedIndex: 0

    property var applications: DesktopEntries.applications.values

    property real animProgress: (launcherVisible || powerVisible) ? 1 : 0
    Behavior on animProgress {
        NumberAnimation { duration: 260; easing.type: Easing.OutExpo }
    }

    signal launcherClosed()
    signal powerClosed()

    function openLauncher() {
        powerVisible = false
        launcherVisible = true
        searchText = ""
        selectedIndex = 0
        Qt.callLater(function() {
            searchField.forceActiveFocus()
        })
    }

    function toggleLauncher() {
        if (launcherVisible) closeLauncher()
        else openLauncher()
    }

    function closeLauncher() {
        launcherVisible = false
        searchText = ""
        launcherClosed()
    }

    function openPower() {
        launcherVisible = false
        powerVisible = true
        Qt.callLater(function() {
            contentItem.forceActiveFocus()
        })
    }

    function togglePower() {
        if (powerVisible) closePower()
        else openPower()
    }

    function closePower() {
        powerVisible = false
        powerClosed()
    }

    function filteredApplications() {
        if (!applications)
            return []

        let result = []
        let query = searchText.toLowerCase().trim()

        for (let i = 0; i < applications.length; ++i) {
            let app = applications[i]
            if (!app || app.noDisplay)
                continue

            let name = String(app.name || "").toLowerCase()
            let comment = String(app.comment || "").toLowerCase()

            if (query === "" || name.includes(query) || comment.includes(query))
                result.push(app)
        }

        return result
    }

    function launchSelected() {
        let list = filteredApplications()
        if (list.length === 0 || selectedIndex < 0 || selectedIndex >= list.length)
            return
        let app = list[selectedIndex]
        if (app && app.execute) {
            app.execute()
            closeLauncher()
        }
    }

    function moveSelection(amount) {
        let count = filteredApplications().length
        if (count === 0) {
            selectedIndex = 0
            return
        }
        selectedIndex = (selectedIndex + amount + count) % count
        appList.positionViewAtIndex(selectedIndex, ListView.Contain)
    }

    function executePower(action) {
        if (action === 1)
            Quickshell.execDetached(["niri", "msg", "action", "quit", "--skip-confirmation"])
        else if (action === 2)
            Quickshell.execDetached(["systemctl", "reboot"])
        else if (action === 3)
            Quickshell.execDetached(["systemctl", "poweroff"])
        closePower()
    }

    anchors {
        top: true
        bottom: true
        left: true
        right: true
    }

    visible: launcherVisible || powerVisible || animProgress > 0.01
    color: "transparent"
    exclusionMode: ExclusionMode.Ignore
    WlrLayershell.layer: WlrLayer.Overlay
    WlrLayershell.keyboardFocus: (launcherVisible || powerVisible) ? WlrKeyboardFocus.Exclusive : WlrKeyboardFocus.None
    WlrLayershell.namespace: "fasdeqos-popups"

    Item {
        id: contentItem
        anchors.fill: parent
        focus: root.launcherVisible || root.powerVisible

        Keys.onEscapePressed: {
            if (root.launcherVisible) root.closeLauncher()
            else root.closePower()
        }

        Keys.onUpPressed: {
            if (root.launcherVisible) root.moveSelection(-1)
        }

        Keys.onDownPressed: {
            if (root.launcherVisible) root.moveSelection(1)
        }

        Keys.onTabPressed: root.moveSelection(1)
        Keys.onBacktabPressed: root.moveSelection(-1)

        Keys.onReturnPressed: {
            if (root.launcherVisible) root.launchSelected()
        }

        Keys.onEnterPressed: {
            if (root.launcherVisible) root.launchSelected()
        }

        Keys.onPressed: function(event) {
            if (!root.powerVisible) return
            if (event.key === Qt.Key_1) {
                root.executePower(1)
                event.accepted = true
            } else if (event.key === Qt.Key_2) {
                root.executePower(2)
                event.accepted = true
            } else if (event.key === Qt.Key_3) {
                root.executePower(3)
                event.accepted = true
            }
        }

        Rectangle {
            anchors.fill: parent
            color: Colors.cOverlay
            opacity: root.animProgress

            MouseArea {
                anchors.fill: parent
                onClicked: {
                    if (root.launcherVisible) root.closeLauncher()
                    else if (root.powerVisible) root.closePower()
                }
            }
        }

        Rectangle {
            id: launcher
            width: Colors.launcherWidth
            height: Colors.launcherHeight
            radius: Colors.uiRadius
            anchors.centerIn: parent
            visible: root.launcherVisible || (opacity > 0.01 && !root.powerVisible)
            color: Colors.cSurface
            border.width: 1
            border.color: Colors.cOutlineVariant

            opacity: root.launcherVisible ? root.animProgress : 0
            scale: 0.93 + 0.07 * opacity
            transform: Translate { y: (1 - launcher.opacity) * 14 }

            MouseArea { anchors.fill: parent }

            ColumnLayout {
                anchors.fill: parent
                anchors.margins: 16
                spacing: 12

                RowLayout {
                    Layout.fillWidth: true
                    Layout.preferredHeight: 40
                    spacing: 12

                    Rectangle {
                        Layout.preferredWidth: 40
                        Layout.preferredHeight: 40
                        radius: Colors.smallRadius
                        color: Colors.cPrimaryContainer

                        Rectangle {
                            anchors.centerIn: parent
                            width: 18
                            height: 18
                            radius: 9
                            color: "transparent"
                            border.width: 2.5
                            border.color: Colors.cPrimary
                        }
                    }

                    ColumnLayout {
                        Layout.fillWidth: true
                        spacing: 1

                        Text {
                            text: "Applications"
                            color: Colors.cOnSurface
                            font.family: Colors.cFontFamily
                            font.pixelSize: 15
                            font.weight: Font.Bold
                        }

                        Text {
                            text: "Find something to launch"
                            color: Colors.cOnSurfaceVariant
                            font.family: Colors.cFontFamily
                            font.pixelSize: 10
                        }
                    }

                    Text {
                        text: "ESC"
                        color: Colors.cInactive
                        font.family: Colors.cFontFamily
                        font.pixelSize: 10
                    }
                }

                Rectangle {
                    Layout.fillWidth: true
                    Layout.fillHeight: true
                    radius: Colors.smallRadius
                    color: Colors.cBackground
                    clip: true

                    ListView {
                        id: appList
                        anchors.fill: parent
                        anchors.margins: 6
                        spacing: 4
                        clip: true
                        model: root.filteredApplications()
                        currentIndex: root.selectedIndex

                        delegate: Rectangle {
                            id: appDelegate
                            required property var modelData
                            required property int index

                            width: appList.width
                            height: 58
                            radius: Colors.smallRadius
                            color: index === root.selectedIndex ? Colors.cSurfaceContainerHighest : "transparent"
                            border.width: index === root.selectedIndex ? 1 : 0
                            border.color: Colors.cPrimaryDim

                            Behavior on color { ColorAnimation { duration: 160 } }

                            RowLayout {
                                anchors.fill: parent
                                anchors.leftMargin: 10
                                anchors.rightMargin: 10
                                spacing: 12

                                Rectangle {
                                    Layout.preferredWidth: 38
                                    Layout.preferredHeight: 38
                                    radius: Colors.smallRadius
                                    color: Colors.cSurfaceContainer

                                    Image {
                                        anchors.centerIn: parent
                                        width: 24
                                        height: 24
                                        source: appDelegate.modelData.icon ? Quickshell.iconPath(appDelegate.modelData.icon, true) : ""
                                        sourceSize.width: 64
                                        sourceSize.height: 64
                                        fillMode: Image.PreserveAspectFit
                                        smooth: true
                                    }
                                }

                                ColumnLayout {
                                    Layout.fillWidth: true
                                    spacing: 2

                                    Text {
                                        Layout.fillWidth: true
                                        text: appDelegate.modelData.name || "Application"
                                        color: Colors.cOnSurface
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 12
                                        font.weight: Font.DemiBold
                                        elide: Text.ElideRight
                                    }

                                    Text {
                                        Layout.fillWidth: true
                                        text: appDelegate.modelData.comment || appDelegate.modelData.genericName || ""
                                        color: Colors.cOnSurfaceVariant
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 9
                                        elide: Text.ElideRight
                                    }
                                }

                                Text {
                                    visible: index === root.selectedIndex
                                    text: "↵"
                                    color: Colors.cPrimary
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 16
                                }
                            }

                            MouseArea {
                                anchors.fill: parent
                                hoverEnabled: true
                                onEntered: root.selectedIndex = appDelegate.index
                                onClicked: {
                                    root.selectedIndex = appDelegate.index
                                    root.launchSelected()
                                }
                            }
                        }

                        ScrollBar.vertical: ScrollBar { active: true }
                    }

                    Text {
                        anchors.centerIn: parent
                        visible: root.filteredApplications().length === 0
                        text: "No applications found"
                        color: Colors.cInactive
                        font.family: Colors.cFontFamily
                        font.pixelSize: 12
                    }
                }

                Rectangle {
                    Layout.fillWidth: true
                    Layout.preferredHeight: 44
                    radius: Colors.smallRadius
                    color: Colors.cSurfaceContainerHigh
                    border.width: 1
                    border.color: searchField.activeFocus ? Colors.cPrimary : Colors.cOutlineVariant

                    Behavior on border.color { ColorAnimation { duration: 160 } }

                    RowLayout {
                        anchors.fill: parent
                        anchors.leftMargin: 12
                        anchors.rightMargin: 12
                        spacing: 10

                        Text {
                            text: "󰍉"
                            color: Colors.cPrimary
                            font.family: Colors.cFontFamily
                            font.pixelSize: 18
                        }

                        TextField {
                            id: searchField
                            Layout.fillWidth: true
                            Layout.fillHeight: true
                            placeholderText: "Search applications..."
                            placeholderTextColor: Colors.cInactive
                            text: root.searchText
                            color: Colors.cOnSurface
                            font.family: Colors.cFontFamily
                            font.pixelSize: 12
                            background: Item {}
                            selectByMouse: true
                            focus: root.launcherVisible

                            onTextChanged: {
                                root.searchText = text
                                root.selectedIndex = 0
                                appList.positionViewAtBeginning()
                            }

                            Keys.onUpPressed: root.moveSelection(-1)
                            Keys.onDownPressed: root.moveSelection(1)
                            Keys.onTabPressed: root.moveSelection(1)
                            Keys.onBacktabPressed: root.moveSelection(-1)
                            Keys.onReturnPressed: root.launchSelected()
                            Keys.onEnterPressed: root.launchSelected()
                            Keys.onEscapePressed: root.closeLauncher()
                        }

                        Text {
                            text: "ESC"
                            color: Colors.cInactive
                            font.family: Colors.cFontFamily
                            font.pixelSize: 9
                        }
                    }
                }
            }
        }

        Rectangle {
            id: powerMenu
            width: 600
            height: 250
            radius: Colors.uiRadius
            color: Colors.cSurface
            border.width: 1
            border.color: Colors.cOutlineVariant
            anchors.centerIn: parent
            visible: root.powerVisible || (opacity > 0.01 && !root.launcherVisible)

            opacity: root.powerVisible ? root.animProgress : 0
            scale: 0.93 + 0.07 * opacity
            transform: Translate { y: (1 - powerMenu.opacity) * 14 }

            MouseArea { anchors.fill: parent }

            ColumnLayout {
                anchors.fill: parent
                anchors.margins: 20
                spacing: 16

                RowLayout {
                    Layout.fillWidth: true

                    ColumnLayout {
                        Layout.fillWidth: true
                        spacing: 2

                        Text {
                            text: "Power menu"
                            color: Colors.cOnSurface
                            font.family: Colors.cFontFamily
                            font.pixelSize: 17
                            font.weight: Font.Bold
                        }

                        Text {
                            text: "Choose a session action"
                            color: Colors.cOnSurfaceVariant
                            font.family: Colors.cFontFamily
                            font.pixelSize: 10
                        }
                    }

                    Text {
                        text: "ESC"
                        color: Colors.cInactive
                        font.family: Colors.cFontFamily
                        font.pixelSize: 10
                    }
                }

                RowLayout {
                    Layout.fillWidth: true
                    Layout.fillHeight: true
                    spacing: 10

                    Repeater {
                        model: [
                            { number: "1", title: "Log Out", icon: "󰍃", description: "End your session", bg: Colors.cPrimaryContainer, fg: Colors.cPrimary },
                            { number: "2", title: "Reboot", icon: "󰜉", description: "Restart your system", bg: Colors.cTertiaryContainer, fg: Colors.cTertiary },
                            { number: "3", title: "Power Off", icon: "⏻", description: "Shut down your system", bg: Colors.cErrorContainer, fg: Colors.cError }
                        ]

                        delegate: Rectangle {
                            id: powerCard
                            required property var modelData
                            required property int index

                            Layout.fillWidth: true
                            Layout.fillHeight: true
                            radius: Colors.smallRadius
                            color: cardMouse.containsMouse ? Colors.cSurfaceContainerHighest : Colors.cSurfaceContainer
                            border.width: 1
                            border.color: cardMouse.containsMouse ? modelData.fg : Colors.cOutlineVariant

                            Behavior on color { ColorAnimation { duration: 160 } }
                            Behavior on border.color { ColorAnimation { duration: 160 } }

                            ColumnLayout {
                                anchors.fill: parent
                                anchors.margins: 12
                                spacing: 8

                                Rectangle {
                                    Layout.preferredWidth: 42
                                    Layout.preferredHeight: 42
                                    radius: Colors.smallRadius
                                    color: powerCard.modelData.bg

                                    Text {
                                        anchors.centerIn: parent
                                        text: powerCard.modelData.icon
                                        color: powerCard.modelData.fg
                                        font.family: Colors.cFontFamily
                                        font.pixelSize: 22
                                    }
                                }

                                Text {
                                    text: powerCard.modelData.title
                                    color: Colors.cOnSurface
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 12
                                    font.weight: Font.Bold
                                }

                                Text {
                                    Layout.fillWidth: true
                                    text: powerCard.modelData.description
                                    color: Colors.cOnSurfaceVariant
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 9
                                    wrapMode: Text.WordWrap
                                }

                                Item { Layout.fillHeight: true }

                                Text {
                                    text: "[" + powerCard.modelData.number + "]"
                                    color: powerCard.modelData.fg
                                    font.family: Colors.cFontFamily
                                    font.pixelSize: 11
                                }
                            }

                            MouseArea {
                                id: cardMouse
                                anchors.fill: parent
                                hoverEnabled: true
                                cursorShape: Qt.PointingHandCursor
                                onClicked: root.executePower(powerCard.index + 1)
                            }
                        }
                    }
                }
            }
        }
    }
}
EOF_QS_POPUPS_QML
chmod 644 /usr/share/fasdeqos/quickshell/Popups.qml
