disabled_colors=#ff777777, #ff0a0a0a, #ff1c1c1c, #ff141414, #ff000000, #ff0f0f0f, #ff777777, #ff999999, #ff777777, #ff000000, #ff050505, #ff000000, #ff4a4a4a, #ff999999, #ff8ab4f8, #ffb388ff, #ff0a0a0a, #ff000000, #ff0a0a0a, #ff777777, #ff777777, #ffb0b0b0
inactive_colors=#ffe6e6e6, #ff0a0a0a, #ff1c1c1c, #ff141414, #ff000000, #ff0f0f0f, #ffe6e6e6, #ffffffff, #ffe6e6e6, #ff000000, #ff050505, #ff000000, #ff4a4a4a, #ffffffff, #ff8ab4f8, #ffb388ff, #ff0a0a0a, #ff000000, #ff0a0a0a, #ffe6e6e6, #ff777777, #ffb0b0b0
