EOF_PACKAGES_INSTALLED
chmod 644 /usr/share/fasdeqos/packages.installed

base64 -d >/usr/share/fasdeqos/logo.ansi <<'EOF_LOGO'

EOF_LOGO
printf 'NAME="FasdeqOS"\nPRETTY_NAME="FasdeqOS"\nID=fasdeqos\nID_LIKE=arch\nVERSION_ID=0.5\nBUILD_ID=rolling\nANSI_COLOR="38;2;226;177;51"\nLOGO=fasdeqos\nHOME_URL="https://github.com/Fasdeq13"\n' >/etc/os-release
sed -i '/^#\[multilib\]/,/^#Include/ s/^#//' /etc/pacman.conf
for f in /usr/share/applications/lstopo.desktop /usr/share/applications/discord.desktop /etc/ostree-mkinitcpio.conf /etc/grub.d/15_ostree; do
    [ -e "$f" ] && ! "$PB" -Qo "$f" >/dev/null 2>&1 && rm -f "$f"
done
"$PB" -Sy --noconfirm
GPU=$(lspci 2>/dev/null | grep -Ei 'vga|3d|display')
GWANT=""
if echo "$GPU" | grep -qiE 'amd|ati|radeon'; then GWANT="$GWANT vulkan-radeon"; else for p in vulkan-radeon lib32-vulkan-radeon; do "$PB" -Qq "$p" >/dev/null 2>&1 && "$PB" -Rns --noconfirm "$p" >/dev/null 2>&1; done; fi
if echo "$GPU" | grep -qi intel; then GWANT="$GWANT vulkan-intel"; else for p in vulkan-intel lib32-vulkan-intel; do "$PB" -Qq "$p" >/dev/null 2>&1 && "$PB" -Rns --noconfirm "$p" >/dev/null 2>&1; done; fi
for p in noctalia noctalia-shell noctalia-qs grub grub-btrfs os-prober ostree alacritty chromium gnome-text-editor easyeffects localsend; do
    "$PB" -Qq "$p" >/dev/null 2>&1 || continue
    if [ "$p" = ostree ] && "$PB" -Qq flatpak >/dev/null 2>&1; then continue; fi
    "$PB" -Rns --noconfirm "$p" >/dev/null 2>&1
done
rm -rf /boot/grub /etc/default/grub /etc/grub.d
OW='/usr/share/applications/*,/usr/share/icons/*,/etc/grub.d/*,/etc/ostree*'
WANT=$(grep -v '^#' /usr/share/fasdeqos/packages.installed | tr '\n' ' ')
WANT="$WANT $GWANT"
for p in steam nautilus-open-any-terminal; do
    "$PB" -Si "$p" >/dev/null 2>&1 && WANT="$WANT $p"
done
NEED=""
for p in $WANT; do
    "$PB" -Qq "$p" >/dev/null 2>&1 || NEED="$NEED $p"
done
[ -n "$NEED" ] && "$PB" -S --needed --noconfirm --overwrite "$OW" $NEED
"$PB" -Syu --noconfirm --overwrite "$OW"
/usr/local/bin/fasd-fasdquery
systemctl daemon-reload
systemctl stop fasd-apps.path fasd-apps.service >/dev/null 2>&1
mkdir -p /etc/skel/.config/fish /etc/skel/.config/ghostty /etc/skel/.config/fastfetch
for d in /Users/* /home/*; do
    [ -d "$d" ] || continue
    u=$(stat -c %U "$d")
    [ "$u" = root ] && continue
    C=$d/.config
    mkdir -p "$C/niri" "$C/fish" "$C/ghostty" "$C/fastfetch" "$C/fasdeqos"
    LAYV=$(sed -n 's/^[[:space:]]*layout "\(.*\)"/\1/p' "$C/niri/config.kdl" 2>/dev/null | head -n 1)
    OPTV=$(sed -n 's/^[[:space:]]*options "\(.*\)"/\1/p' "$C/niri/config.kdl" 2>/dev/null | head -n 1)
    OUTS=$(awk '/^output "/ {p=1} p {print} /^}/ {p=0}' "$C/niri/config.kdl" 2>/dev/null)
    [ -n "$LAYV" ] || LAYV=us
    {
        cat <<'EOK'
prefer-no-csd

hotkey-overlay {
    skip-at-startup
}

EOK
        printf 'input {\n    keyboard {\n        xkb {\n            layout "%s"\n' "$LAYV"
        [ -n "$OPTV" ] && printf '            options "%s"\n' "$OPTV"
        printf '        }\n    }\n    touchpad {\n        tap\n        dwt\n        natural-scroll\n        click-method "clickfinger"\n        scroll-method "two-finger"\n    }\n}\n'
        cat <<'EOK'

layout {
    gaps 6
    center-focused-column "never"
    default-column-width { proportion 0.5; }
}

window-rule {
    geometry-corner-radius 8
    clip-to-geometry true
}

window-rule {
    match app-id="^(Throne)$"
    open-floating true
}


window-rule {
    match app-id="^steam_app_.*"
    match app-id="^gamescope"
    open-fullscreen true
}
binds {
    Mod+O { toggle-overview; }
    Mod+T { spawn "ghostty"; }
    Mod+Return { spawn "ghostty"; }
    Mod+E { spawn "nautilus"; }
    Ctrl+Alt+E { spawn "nautilus"; }
    Ctrl+Alt+T { spawn "ghostty"; }
    Mod+B { spawn "firefox"; }
    Mod+Q { close-window; }
    Alt+F4 { close-window; }
    Mod+F { maximize-column; }
    Mod+Shift+F { fullscreen-window; }
    Mod+Shift+V { toggle-window-floating; }
    Mod+W { focus-window-or-workspace-up; }
    Mod+A { focus-column-left; }
    Mod+S { focus-window-or-workspace-down; }
    Mod+D { focus-column-right; }
    Mod+Left { focus-column-left; }
    Mod+Right { focus-column-right; }
    Mod+Up { focus-window-or-workspace-up; }
    Mod+Down { focus-window-or-workspace-down; }
    Mod+Shift+Left { move-column-left; }
    Mod+Shift+Right { move-column-right; }
    Mod+Shift+Up { move-window-up-or-to-workspace-up; }
    Mod+Shift+Down { move-window-down-or-to-workspace-down; }
    Mod+Minus { set-column-width "-10%"; }
    Mod+Shift+Minus { set-window-height "-10%"; }
    Mod+Equal { set-column-width "+10%"; }
    Mod+Shift+Equal { set-window-height "+10%"; }
    Mod+1 { focus-workspace 1; }
    Mod+2 { focus-workspace 2; }
    Mod+3 { focus-workspace 3; }
    Mod+4 { focus-workspace 4; }
    Mod+5 { focus-workspace 5; }
    Mod+6 { focus-workspace 6; }
    Mod+7 { focus-workspace 7; }
    Mod+8 { focus-workspace 8; }
    Mod+9 { focus-workspace 9; }
    Mod+Ctrl+1 { move-column-to-workspace 1; }
    Mod+Ctrl+2 { move-column-to-workspace 2; }
    Mod+Ctrl+3 { move-column-to-workspace 3; }
    Mod+Ctrl+4 { move-column-to-workspace 4; }
    Mod+Ctrl+5 { move-column-to-workspace 5; }
    Mod+Ctrl+6 { move-column-to-workspace 6; }
    Mod+Ctrl+7 { move-column-to-workspace 7; }
    Mod+Ctrl+8 { move-column-to-workspace 8; }
    Mod+Ctrl+9 { move-column-to-workspace 9; }
    Mod+Shift+S { spawn "qs" "ipc" "call" "shell" "screenshotArea"; }
    Print { spawn "qs" "ipc" "call" "shell" "screenshotScreen"; }
    Mod+Print { spawn "qs" "ipc" "call" "shell" "screenshot"; }
    Alt+Space { spawn "qs" "ipc" "call" "shell" "launcher"; }
    Mod+Shift+P { spawn "qs" "ipc" "call" "shell" "power"; }
    Mod+Shift+A { spawn "qs" "ipc" "call" "shell" "settings"; }
    Mod+Shift+C { spawn "qs" "ipc" "call" "shell" "calendar"; }
    Mod+Shift+M { spawn "qs" "ipc" "call" "shell" "audio"; }
    Mod+Shift+N { spawn "qs" "ipc" "call" "shell" "network"; }
    Mod+Shift+B { spawn "qs" "ipc" "call" "shell" "bluetooth"; }
    Alt+Print { spawn "qs" "ipc" "call" "shell" "screenshotWindow"; }
    XF86AudioRaiseVolume allow-when-locked=true { spawn "wpctl" "set-volume" "-l" "1.5" "@DEFAULT_AUDIO_SINK@" "5%+"; }
    XF86AudioLowerVolume allow-when-locked=true { spawn "wpctl" "set-volume" "@DEFAULT_AUDIO_SINK@" "5%-"; }
    XF86AudioMute allow-when-locked=true { spawn "wpctl" "set-mute" "@DEFAULT_AUDIO_SINK@" "toggle"; }
    XF86AudioPlay allow-when-locked=true { spawn "playerctl" "play-pause"; }
    XF86AudioNext allow-when-locked=true { spawn "playerctl" "next"; }
    XF86AudioPrev allow-when-locked=true { spawn "playerctl" "previous"; }
    XF86MonBrightnessUp allow-when-locked=true { spawn "brightnessctl" "set" "5%+"; }
    XF86MonBrightnessDown allow-when-locked=true { spawn "brightnessctl" "set" "5%-"; }
    Mod+Shift+Slash { show-hotkey-overlay; }
    Mod+K { show-hotkey-overlay; }
    Mod+Shift+E { quit; }
    Mod+TouchpadScrollDown cooldown-ms=200 { focus-workspace-down; }
    Mod+TouchpadScrollUp cooldown-ms=200 { focus-workspace-up; }
    Mod+TouchpadScrollRight { focus-column-right; }
    Mod+TouchpadScrollLeft { focus-column-left; }
    Mod+Shift+TouchpadScrollDown cooldown-ms=200 { move-column-to-workspace-down; }
    Mod+Shift+TouchpadScrollUp cooldown-ms=200 { move-column-to-workspace-up; }
    Mod+Shift+TouchpadScrollRight { move-column-right; }
    Mod+Shift+TouchpadScrollLeft { move-column-left; }
    Mod+Ctrl+TouchpadScrollUp { set-window-height "+5%"; }
    Mod+Ctrl+TouchpadScrollDown { set-window-height "-5%"; }
    Mod+Ctrl+TouchpadScrollRight { set-column-width "+5%"; }
    Mod+Ctrl+TouchpadScrollLeft { set-column-width "-5%"; }
    Mod+WheelScrollDown cooldown-ms=150 { focus-workspace-down; }
    Mod+WheelScrollUp cooldown-ms=150 { focus-workspace-up; }
    Mod+WheelScrollRight { focus-column-right; }
    Mod+WheelScrollLeft { focus-column-left; }
    Mod+Shift+WheelScrollDown cooldown-ms=150 { move-column-to-workspace-down; }
    Mod+Shift+WheelScrollUp cooldown-ms=150 { move-column-to-workspace-up; }
}


gestures {
    hot-corners {
        off
    }
}
EOK
        printf '\nspawn-at-startup "/usr/local/bin/fasd-first"\nspawn-at-startup "qs"\nspawn-at-startup "/usr/local/bin/fasd-wallpaper"\nspawn-at-startup "/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1"\nspawn-at-startup "xdg-user-dirs-update"\nspawn-at-startup "gnome-keyring-daemon" "--start" "--components=secrets"\n'
        cat <<'EOK'

window-rule {
    match app-id=r#"^steam$"# title=r#"^notificationtoasts_\d+_desktop$"#
    default-floating-position x=10 y=10 relative-to="bottom-right"
    open-focused false
}

window-rule {
    match app-id=r#"^steam$"#
    exclude title=r#"^Steam$"#
    open-floating true
}
EOK
        printf '\nenvironment {\n    QT_QPA_PLATFORMTHEME "qt6ct"\n}\n\ninclude "colors.kdl"\n'
    } >"$C/niri/config.kdl"
    [ -n "$OUTS" ] && printf '\n%s\n' "$OUTS" >>"$C/niri/config.kdl"
    printf 'set -g fish_greeting\nif status is-interactive\n    starship init fish | source\nend\n' >"$C/fish/config.fish"
    cat >"$C/ghostty/config" <<'EOP'
window-decoration = none
background-opacity = 0.95
font-family = JetBrainsMono Nerd Font
font-size = 11
window-padding-x = 8
window-padding-y = 8
theme = Catppuccin Mocha
confirm-close-surface = false
EOP
    cat >"$C/fastfetch/config.jsonc" <<'EOP'
{
  "logo": { "type": "file-raw", "source": "/usr/share/fasdeqos/logo.ansi", "padding": { "top": 1, "right": 3 } },
  "display": { "separator": "  ", "color": { "keys": "yellow", "title": "yellow" } },
  "modules": [
    "title",
    "separator",
    { "type": "os", "key": " OS", "format": "{name}" },
    { "type": "kernel", "key": " Kernel" },
    { "type": "uptime", "key": " Uptime" },
    { "type": "packages", "key": " Packages", "format": "{all}" },
    { "type": "shell", "key": " Shell" },
    { "type": "wm", "key": " WM" },
    { "type": "terminal", "key": " Terminal" },
    { "type": "cpu", "key": " CPU" },
    { "type": "gpu", "key": " GPU" },
    { "type": "memory", "key": " Memory" },
    { "type": "disk", "key": " Disk", "folders": "/" },
    "break",
    "colors"
  ]
}
EOP
    mkdir -p "$C/quickshell" "$C/gtk-3.0" "$C/gtk-4.0" "$C/qt6ct"
    cp -f /usr/share/fasdeqos/quickshell/*.qml "$C/quickshell/"
    cp -f /usr/share/fasdeqos/theme/gtk.css "$C/gtk-3.0/gtk.css"
    cp -f /usr/share/fasdeqos/theme/gtk.css "$C/gtk-4.0/gtk.css"
    cp -f /usr/share/fasdeqos/theme/qt6ct.conf "$C/qt6ct/qt6ct.conf"
    : >"$C/niri/colors.kdl"
    rm -rf "$C/noctalia" "$d/.cache/noctalia" "$d/.local/share/noctalia"
    find "$C" -maxdepth 4 -iname '*noctalia*' -not -path "$C/quickshell/*" -exec rm -rf {} + 2>/dev/null
    for f in gtk-3.0 gtk-4.0 qt5ct qt6ct ghostty fish btop; do
        grep -rIl -i noctalia "$C/$f" 2>/dev/null | while read -r x; do sed -i '/[Nn]octalia/d' "$x"; done
    done
    rm -f "$C/fasdeqos/first-done" "$C/starship.toml"
    chown -R "$u:$(id -gn "$u")" "$C"
done
if [ ! -f /var/lib/fasdeqos/shells-v1 ]; then
    : >/var/lib/fasdeqos/layout.list
    rm -rf /Applications/*.app /Applications/tui/*
    touch /var/lib/fasdeqos/shells-v1
fi
/usr/local/bin/fasd-layout
/usr/local/bin/fasd-pkgbackend
systemctl enable --now fasd-apps.path >/dev/null 2>&1
echo "FasdeqOS updated. Log out and back in to apply the new configuration."
